var VERYL_EXAMPLES = [{"id":"adder","group":"基礎","title":"Adder 加法器","files":[{"name":"adder.veryl","src":"module Adder (\n    i_a: input  logic<8>,\n    i_b: input  logic<8>,\n    o_s: output logic<8>,\n) {\n    assign o_s = i_a + i_b;\n}\n\n#[test(test_adder)]\nmodule TestAdder {\n    var a: logic<8>;\n    var b: logic<8>;\n    var s: logic<8>;\n\n    inst uut: Adder (\n        i_a: a,\n        i_b: b,\n        o_s: s,\n    );\n\n    initial {\n        a = 8'd10;\n        b = 8'd20;\n\n        // 官方原生支援的斷言與結束\n        $assert(s == 8'd30);\n        $finish();\n    }\n}"}],"synth":"Adder","title_en":"Adder","group_en":"Basics"},{"id":"max3","group":"基礎","title":"Max3 function","files":[{"name":"max3.veryl","src":"// ==========================================\n// 使用者 function：組合邏輯\n// ==========================================\nmodule Max3 (\n    i_a: input  logic<8>,\n    i_b: input  logic<8>,\n    i_c: input  logic<8>,\n    o_m: output logic<8>,\n) {\n    function max2 (\n        x: input logic<8>,\n        y: input logic<8>,\n    ) -> logic<8> {\n        if (x >: y) {\n            return x;\n        } else {\n            return y;\n        }\n    }\n\n    assign o_m = max2(max2(i_a, i_b), i_c);\n}\n\n#[test(max3_test)]\nmodule TestMax3 {\n    var a: logic<8>;\n    var b: logic<8>;\n    var c: logic<8>;\n    var m: logic<8>;\n\n    inst u: Max3 (\n        i_a: a,\n        i_b: b,\n        i_c: c,\n        o_m: m,\n    );\n\n    initial {\n        a = 8'd5;  b = 8'd9; c = 8'd2;\n        $assert(m == 8'd9, \"max in b\");\n        a = 8'd42; b = 8'd9; c = 8'd17;\n        $assert(m == 8'd42, \"max in a\");\n        a = 8'd1;  b = 8'd2; c = 8'd3;\n        $assert(m == 8'd3, \"max in c\");\n        $finish();\n    }\n}\n"}],"synth":"Max3","title_en":"Max3 function","group_en":"Basics"},{"id":"alu_pkg","group":"基礎","title":"AluUnit package + enum","files":[{"name":"alu_pkg.veryl","src":"// ==========================================\n// Package + enum：ALU（組合邏輯）\n// ==========================================\npackage AluPkg {\n    enum Op: logic<2> {\n        ADD = 2'd0,\n        SUB = 2'd1,\n        AND = 2'd2,\n        OR  = 2'd3,\n    }\n}\n\nmodule AluUnit (\n    i_op: input  AluPkg::Op,\n    i_a  : input  logic<8>,\n    i_b  : input  logic<8>,\n    o_y  : output logic<8>,\n) {\n    always_comb {\n        case i_op {\n            AluPkg::Op::ADD: o_y = i_a + i_b;\n            AluPkg::Op::SUB: o_y = i_a - i_b;\n            AluPkg::Op::AND: o_y = i_a & i_b;\n            AluPkg::Op::OR : o_y = i_a | i_b;\n            default    : o_y = 8'd0;\n        }\n    }\n}\n\n#[test(alu_ops)]\nmodule TestAlu {\n    var op: AluPkg::Op;\n    var a : logic<8>;\n    var b : logic<8>;\n    var y : logic<8>;\n\n    inst u: AluUnit (\n        i_op: op,\n        i_a : a,\n        i_b : b,\n        o_y : y,\n    );\n\n    initial {\n        a = 8'd10;\n        b = 8'd20;\n\n        op = AluPkg::Op::ADD;\n        $assert(y == 8'd30, \"add\");\n        op = AluPkg::Op::SUB;\n        $assert(y == 8'hF6, \"sub 10-20 (wraps)\");\n        op = AluPkg::Op::AND;\n        $assert(y == 8'd0,  \"and\");\n        op = AluPkg::Op::OR;\n        $assert(y == 8'd30, \"or\");\n\n        $finish();\n    }\n}\n"}],"synth":"AluUnit","title_en":"AluUnit package + enum","group_en":"Basics"},{"id":"gen_rev","group":"基礎","title":"BitRev / GrayConv generate","files":[{"name":"gen_rev.veryl","src":"// ==========================================\n// generate for / if：參數化的位元反轉器\n// ==========================================\nmodule BitRev #(\n    param W: u32 = 4,\n) (\n    i_x: input  logic<W>,\n    o_y: output logic<W>,\n) {\n    for i in 0..W : gen_rev {\n        assign o_y[i] = i_x[W - 1 - i];\n    }\n}\n\nmodule GrayConv #(\n    param W: u32 = 4,\n) (\n    i_bin: input  logic<W>,\n    o_gray: output logic<W>,\n) {\n    assign o_gray = i_bin ^ (i_bin >> 1);\n}\n\n#[test(gen_test)]\nmodule TestGen {\n    var x: logic<4>;\n    var y: logic<4>;\n    var b: logic<4>;\n    var g: logic<4>;\n\n    inst u_rev: BitRev #(W: 4) (\n        i_x: x,\n        o_y: y,\n    );\n    inst u_gray: GrayConv #(W: 4) (\n        i_bin: b,\n        o_gray: g,\n    );\n\n    initial {\n        x = 4'b1001;\n        $assert(y == 4'b1001, \"palindrome\");\n        x = 4'b0001;\n        $assert(y == 4'b1000, \"reverse lsb->msb\");\n\n        b = 4'b0101;\n        $assert(g == 4'b0111, \"binary->gray\");\n        b = 4'b0111;\n        $assert(g == 4'b0100, \"binary->gray 2\");\n\n        $finish();\n    }\n}\n"}],"synth":"GrayConv","title_en":"BitRev / GrayConv generate","group_en":"Basics"},{"id":"seq101","group":"時序","title":"Seq101 狀態機","files":[{"name":"seq101.veryl","src":"// ==========================================\n// enum 狀態機：Moore 式 \"101\" 序列偵測器\n// ==========================================\npackage SeqPkg {\n    enum St: logic<2> {\n        S0 = 2'd0, // 尚未比對到任何位元\n        S1 = 2'd1, // 已比對到 '1'\n        S2 = 2'd2, // 已比對到 '10'\n    }\n}\n\nmodule Seq101 (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    i_sig: input  logic,\n    o_hit: output logic,\n) {\n    var st: SeqPkg::St;\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            st = SeqPkg::St::S0;\n        } else {\n            case st {\n                SeqPkg::St::S0: {\n                    if (i_sig) { st = SeqPkg::St::S1; } else { st = SeqPkg::St::S0; }\n                }\n                SeqPkg::St::S1: {\n                    if (i_sig) { st = SeqPkg::St::S1; } else { st = SeqPkg::St::S2; }\n                }\n                SeqPkg::St::S2: {\n                    if (i_sig) { st = SeqPkg::St::S1; } else { st = SeqPkg::St::S0; }\n                }\n                default: st = SeqPkg::St::S0;\n            }\n        }\n    }\n\n    assign o_hit = (st == SeqPkg::St::S2) && i_sig;\n}\n\n#[test(seq101_test)]\nmodule TestSeq101 {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var sig: logic;\n    var hit: logic;\n\n    inst u: Seq101 (\n        i_clk: clk,\n        i_rst: rst,\n        i_sig: sig,\n        o_hit: hit,\n    );\n\n    initial {\n        rst.assert();\n\n        // 餵入序列 1, 0, 1 → 應偵測到 \"101\"\n        // （st == S2 且當下輸入為 1 時，在下一個 rising edge 之前就該命中）\n        sig = 1; clk.next();\n        sig = 0; clk.next();\n        sig = 1;\n        $assert(hit, \"101 detected\");\n        clk.next();\n\n        // '0' 之後應回到未命中\n        sig = 0; clk.next();\n        $assert(!hit, \"no hit after break\");\n\n        // 序列 1, 1, 0, 1 → 命中\n        sig = 1; clk.next();\n        sig = 1; clk.next();\n        sig = 0; clk.next();\n        sig = 1;\n        $assert(hit, \"101 detected across restart\");\n        clk.next();\n\n        $finish();\n    }\n}\n"}],"synth":"Seq101","title_en":"Seq101 state machine","group_en":"Sequential"},{"id":"pkt_reg","group":"時序","title":"PktReg struct 暫存器","files":[{"name":"pkt_reg.veryl","src":"// ==========================================\n// struct + 暫存器群\n// ==========================================\npackage PktPkg {\n    struct Pkt {\n        valid: logic,\n        data : logic<8>,\n    }\n}\n\nmodule PktReg (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    i_d  : input  PktPkg::Pkt,\n    o_q  : output PktPkg::Pkt,\n) {\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            o_q.valid = '0;\n            o_q.data  = 8'd0;\n        } else {\n            o_q.valid = i_d.valid;\n            o_q.data  = i_d.data;\n        }\n    }\n}\n\n#[test(pkt_reg_test)]\nmodule TestPktReg {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var d: PktPkg::Pkt;\n    var q: PktPkg::Pkt;\n\n    inst u: PktReg (\n        i_clk: clk,\n        i_rst: rst,\n        i_d  : d,\n        o_q  : q,\n    );\n\n    initial {\n        rst.assert();\n\n        d.valid = 1;\n        d.data  = 8'hAB;\n        clk.next();\n        $assert(q.valid == 1 && q.data == 8'hAB, \"captured\");\n\n        d.valid = 0;\n        d.data  = 8'hFF;\n        clk.next();\n        $assert(q.valid == 0 && q.data == 8'hFF, \"second beat\");\n\n        $finish();\n    }\n}\n"}],"synth":"PktReg","title_en":"PktReg struct register","group_en":"Sequential"},{"id":"ram","group":"時序","title":"Ram 16×8","files":[{"name":"ram.veryl","src":"// ==========================================\n// 陣列：16 x 8bit 同步寫、非同步讀 RAM\n// ==========================================\nmodule Ram (\n    i_clk  : input  clock,\n    i_rst  : input  reset,\n    i_we   : input  logic,\n    i_addr : input  logic<4>,\n    i_wdata: input  logic<8>,\n    o_rdata: output logic<8>,\n) {\n    var mem: logic<8> [16];\n\n    #[allow(missing_reset_statement)]\n    always_ff (i_clk, i_rst) {\n        if_reset {\n        } else if (i_we) {\n            mem[i_addr] = i_wdata;\n        }\n    }\n\n    assign o_rdata = mem[i_addr];\n}\n\n#[test(ram_test)]\nmodule TestRam {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var we   : logic;\n    var addr : logic<4>;\n    var wdata: logic<8>;\n    var rdata: logic<8>;\n\n    inst u: Ram (\n        i_clk  : clk,\n        i_rst  : rst,\n        i_we   : we,\n        i_addr : addr,\n        i_wdata: wdata,\n        o_rdata: rdata,\n    );\n\n    initial {\n        rst.assert();\n\n        // 寫入兩個位置\n        we = 1;\n        addr = 4'd3;  wdata = 8'h5A; clk.next();\n        addr = 4'd12; wdata = 8'hC3; clk.next();\n        we = 0;\n\n        // 非同步讀回\n        addr = 4'd3;\n        $assert(rdata == 8'h5A, \"read back 3\");\n        addr = 4'd12;\n        $assert(rdata == 8'hC3, \"read back 12\");\n\n        $finish();\n    }\n}\n"}],"synth":"Ram","title_en":"Ram 16×8","group_en":"Sequential"},{"id":"sync_ram","group":"時序","title":"SyncRam 同步讀取 RAM → block RAM","files":[{"name":"sync_ram.veryl","src":"// ==========================================\n// 同步讀取 RAM：讀取位址在時脈正緣取樣，下一拍才有資料\n// （iCE40 block RAM 的行為：合成到 FPGA 時會變成 SB_RAM40_4K）\n// ==========================================\nmodule SyncRam #(\n    param ADDR_W: u32 = 9,\n    param DATA_W: u32 = 8,\n) (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<ADDR_W>,\n    i_wdata: input  logic<DATA_W>,\n    i_re   : input  logic,\n    i_raddr: input  logic<ADDR_W>,\n    o_rdata: output logic<DATA_W>,\n) {\n    var mem: logic<DATA_W> [1 << ADDR_W];\n\n    always_ff (i_clk) {\n        if i_we {\n            mem[i_waddr] = i_wdata;\n        }\n        if i_re {\n            o_rdata = mem[i_raddr];\n        }\n    }\n}\n\n#[test(sync_ram_test)]\nmodule TestSyncRam {\n    inst clk: $tb::clock_gen;\n\n    var we   : logic;\n    var waddr: logic<9>;\n    var wdata: logic<8>;\n    var re   : logic;\n    var raddr: logic<9>;\n    var rdata: logic<8>;\n\n    inst u: SyncRam (\n        i_clk  : clk,\n        i_we   : we,\n        i_waddr: waddr,\n        i_wdata: wdata,\n        i_re   : re,\n        i_raddr: raddr,\n        o_rdata: rdata,\n    );\n\n    initial {\n        re = 1;\n        we = 1;\n        waddr = 9'd5;   wdata = 8'h5A; clk.next();\n        waddr = 9'd300; wdata = 8'hC3; clk.next();\n        waddr = 9'd511; wdata = 8'h7E; clk.next();\n        we = 0;\n\n        // 讀取：下一拍才出現\n        raddr = 9'd300; clk.next();\n        $assert(rdata == 8'hC3, \"read 300\");\n        raddr = 9'd5;   clk.next();\n        $assert(rdata == 8'h5A, \"read 5\");\n        raddr = 9'd511; clk.next();\n        $assert(rdata == 8'h7E, \"read 511\");\n\n        // 讀取致能關閉時輸出保持\n        re = 0;\n        raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h7E, \"hold when re = 0\");\n\n        // 同一拍讀寫同一位址：讀到舊值\n        re = 1;\n        we = 1;\n        waddr = 9'd5; wdata = 8'h11; raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h5A, \"read-during-write returns the old value\");\n        we = 0;\n        clk.next();\n        $assert(rdata == 8'h11, \"new value next cycle\");\n        $finish();\n    }\n}\n"}],"synth":"SyncRam","title_en":"SyncRam synchronous-read RAM → block RAM","group_en":"Sequential"},{"id":"fifo","group":"時序","title":"FIFO 256×8（block RAM）","files":[{"name":"fifo.veryl","src":"// ==========================================\n// 同步 FIFO：256 × 8，記憶體同步讀取（FPGA 上是一塊 block RAM）\n// 讀出的資料在 i_pop 的下一拍出現在 o_data\n// ==========================================\nmodule Fifo #(\n    param ADDR_W: u32 = 8,\n    param DATA_W: u32 = 8,\n) (\n    i_clk  : input  clock        ,\n    i_rst  : input  reset        ,\n    i_push : input  logic        ,\n    i_data : input  logic<DATA_W>,\n    i_pop  : input  logic        ,\n    o_data : output logic<DATA_W>,\n    o_empty: output logic        ,\n    o_full : output logic        ,\n    o_count: output logic<ADDR_W + 1>,\n) {\n    var mem  : logic<DATA_W> [1 << ADDR_W];\n    var wp   : logic<ADDR_W>    ;\n    var rp   : logic<ADDR_W>    ;\n    var count: logic<ADDR_W + 1>;\n    var rdata: logic<DATA_W>    ;\n\n    let do_push: logic = i_push && (count != (1 << ADDR_W));\n    let do_pop : logic = i_pop && (count != 0);\n\n    always_ff (i_clk) {\n        if do_push {\n            mem[wp] = i_data;\n        }\n        if do_pop {\n            rdata = mem[rp];\n        }\n    }\n\n    always_ff {\n        if_reset {\n            wp    = 0;\n            rp    = 0;\n            count = 0;\n        } else {\n            if do_push {\n                wp = wp + 1;\n            }\n            if do_pop {\n                rp = rp + 1;\n            }\n            if do_push && !do_pop {\n                count = count + 1;\n            } else if do_pop && !do_push {\n                count = count - 1;\n            }\n        }\n    }\n\n    assign o_data  = rdata;\n    assign o_count = count;\n    assign o_empty = count == 0;\n    assign o_full  = count == (1 << ADDR_W);\n}\n\n#[test(fifo_test)]\nmodule TestFifo {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var push : logic   ;\n    var din  : logic<8>;\n    var pop  : logic   ;\n    var dout : logic<8>;\n    var empty: logic   ;\n    var full : logic   ;\n    var count: logic<9>;\n\n    inst u: Fifo (\n        i_clk  : clk  ,\n        i_rst  : rst  ,\n        i_push : push ,\n        i_data : din  ,\n        i_pop  : pop  ,\n        o_data : dout ,\n        o_empty: empty,\n        o_full : full ,\n        o_count: count,\n    );\n\n    initial {\n        push = 0;\n        pop  = 0;\n        din  = 0;\n        rst.assert();\n        $assert(empty == 1'b1, \"empty after reset\");\n        // push 3 bytes\n        push = 1;\n        din = 8'h11; clk.next();\n        din = 8'h22; clk.next();\n        din = 8'h33; clk.next();\n        push = 0;\n        $assert(count == 9'd3, \"three in\");\n        // pop them in order (data one cycle later)\n        pop = 1;\n        clk.next();\n        $assert(dout == 8'h11, \"first out\");\n        clk.next();\n        $assert(dout == 8'h22, \"second out\");\n        clk.next();\n        $assert(dout == 8'h33, \"third out\");\n        pop = 0;\n        $assert(empty == 1'b1, \"empty again\");\n        // fill it up\n        push = 1;\n        din  = 0;\n        for _i in 0..256 {\n            clk.next();\n            din = din + 8'd1;\n        }\n        $assert(full == 1'b1, \"full after 256\");\n        din = 8'hFF;\n        clk.next();\n        $assert(count == 9'd256, \"no push when full\");\n        $finish();\n    }\n}\n"}],"synth":"Fifo","note":"同步讀取的記憶體 → 一塊 SB_RAM40_4K / 一個 SRAM 巨集","title_en":"FIFO 256×8 (block RAM)","note_en":"Synchronous-read memory → one SB_RAM40_4K / one SRAM macro","group_en":"Sequential"},{"id":"counter","group":"時序","title":"Counter（veryl-sim 範例）","files":[{"name":"counter.veryl","src":"module Counter #(\n    param WIDTH: u32 = 8,\n) (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    i_en : input  logic,\n    o_cnt: output logic<WIDTH>,\n) {\n    var cnt: logic<WIDTH>;\n\n    always_ff {\n        if_reset {\n            cnt = 0;\n        } else if i_en {\n            cnt += 1;\n        }\n    }\n\n    assign o_cnt = cnt;\n}\n\n#[test(counter_basic)]\nmodule tb_counter {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen;\n\n    var en : logic;\n    var cnt: logic<4>;\n\n    inst dut: Counter #(WIDTH: 4) (\n        i_clk: clk,\n        i_rst: rst,\n        i_en : en,\n        o_cnt: cnt,\n    );\n\n    initial {\n        en = 1;\n        rst.assert(clk);\n        clk.next(5);\n        $display(\"t=%t cnt=%d (0x%h, 0b%b)\", $time, cnt, cnt, cnt);\n        $assert(cnt == 5, \"cnt should be 5\");\n        clk.next(12);\n        $display(\"t=%t cnt=%d (wraps at 16)\", $time, cnt);\n        $assert(cnt == 1);\n        en = 0;\n        clk.next(3);\n        $assert(cnt == 1, \"cnt must hold when disabled\");\n        $finish();\n    }\n}\n"}],"synth":"Counter","title_en":"Counter (veryl-sim example)","group_en":"Sequential"},{"id":"features","group":"綜合","title":"features：移位/函式/範圍/計數器","files":[{"name":"features.veryl","src":"// veryl-eda feature coverage: every module here is checked for formal\n// equivalence against `veryl build` output by test.sh\npackage FeatPkg {\n    const ONES: logic<4> = 4'hf;\n    struct Pair {\n        hi: logic<4>,\n        lo: logic<4>,\n    }\n}\n\nmodule Shifter #(\n    param W: u32 = 8,\n) (\n    i_a  : input  logic<W>,\n    i_n  : input  logic<3>,\n    i_op : input  logic<2>,\n    o_y  : output logic<W>,\n    o_sl : output logic<4>,\n) {\n    always_comb {\n        switch {\n            i_op == 2'd0: o_y = i_a << i_n;\n            i_op == 2'd1: o_y = i_a >> i_n;\n            i_op == 2'd2: o_y = $signed(i_a) >>> i_n;\n            default     : o_y = {i_a[3:0], i_a[W - 1:4]};\n        }\n    }\n    assign o_sl = i_a[i_n+:4];\n}\n\nmodule Funcs (\n    i_x : input  logic<8>,\n    i_k : input  logic<8>,\n    o_c : output logic<4>,\n    o_r : output logic<4>,\n    o_m : output logic<16>,\n    o_p : output FeatPkg::Pair,\n) {\n    function popcnt (\n        x: input logic<8>,\n    ) -> logic<4> {\n        var n: logic<4>;\n        n = 0;\n        for i in 0..8 {\n            n += x[i];\n        }\n        return n;\n    }\n\n    function clamp (\n        v: input logic<8>,\n    ) -> logic<4> {\n        if v >= 8'd15 {\n            return 4'd15;\n        }\n        if v == 8'd0 {\n            return 4'd1;\n        }\n        return v[3:0];\n    }\n\n    assign o_c = popcnt(i_x);\n    assign o_r = clamp(i_k);\n    assign o_m = i_x * i_k;\n    always_comb {\n        o_p.hi = i_x[7:4] ^ FeatPkg::ONES;\n        o_p.lo = if &i_k[1:0] ? i_x[3:0] : ~i_x[3:0];\n    }\n}\n\nmodule Ranges (\n    i_v : input  logic<6>,\n    o_cl: output logic<2>,\n    o_rv: output logic<6>,\n) {\n    always_comb {\n        case i_v {\n            0..10  : o_cl = 2'd0;\n            10..=20: o_cl = 2'd1;\n            21, 22 : o_cl = 2'd2;\n            default: o_cl = 2'd3;\n        }\n    }\n    for i in 0..6 : g {\n        if i % 2 == 0 : even {\n            assign o_rv[i] = i_v[5 - i];\n        } else {\n            assign o_rv[i] = ~i_v[5 - i];\n        }\n    }\n}\n\nmodule Counter #(\n    param INIT: u32 = 5,\n) (\n    i_clk: input  clock_negedge,\n    i_rst: input  reset_sync_high,\n    i_en : input  logic,\n    o_q  : output logic<4>,\n) {\n    var cnt: logic<4>;\n    always_ff {\n        if_reset {\n            cnt = INIT;\n        } else if i_en {\n            cnt += 1;\n        }\n    }\n    assign o_q = cnt;\n}\n\nmodule Top (\n    i_clk: input  clock_negedge,\n    i_rst: input  reset_sync_high,\n    i_en : input  logic,\n    o_a  : output logic<4>,\n    o_b  : output logic<4>,\n) {\n    inst c0: Counter #(INIT: 3) (\n        i_clk,\n        i_rst,\n        i_en ,\n        o_q  : o_a,\n    );\n    inst c1: Counter (\n        i_clk,\n        i_rst,\n        i_en : ~i_en,\n        o_q  : o_b,\n    );\n}\n\n// ---------------- testbenches (veryl test / veryl-sim) ----------------\n\n#[test(test_shifter)]\nmodule TestShifter {\n    var a : logic<8>;\n    var n : logic<3>;\n    var op: logic<2>;\n    var y : logic<8>;\n    var sl: logic<4>;\n\n    inst u: Shifter #(W: 8) (\n        i_a : a ,\n        i_n : n ,\n        i_op: op,\n        o_y : y ,\n        o_sl: sl,\n    );\n\n    initial {\n        a  = 8'h96;\n        n  = 3'd3;\n        op = 2'd0;\n        $assert(y == 8'hb0, \"<<\");\n        op = 2'd1;\n        $assert(y == 8'h12, \">>\");\n        op = 2'd2;\n        $assert(y == 8'hf2, \">>> keeps the sign\");\n        op = 2'd3;\n        $assert(y == 8'h69, \"nibble swap\");\n        $assert(sl == 4'h2, \"variable +: slice\");\n        n = 3'd0;\n        $assert(sl == 4'h6, \"+: slice at 0\");\n        $finish();\n    }\n}\n\n#[test(test_funcs)]\nmodule TestFuncs {\n    var x: logic<8>;\n    var k: logic<8>;\n    var c: logic<4>;\n    var r: logic<4>;\n    var m: logic<16>;\n    var p: FeatPkg::Pair;\n\n    inst u: Funcs (\n        i_x: x,\n        i_k: k,\n        o_c: c,\n        o_r: r,\n        o_m: m,\n        o_p: p,\n    );\n\n    initial {\n        x = 8'hb5;\n        k = 8'd20;\n        $assert(c == 4'd5, \"popcount\");\n        $assert(r == 4'd15, \"clamp high\");\n        $assert(m == 16'd3620, \"multiply\");\n        $assert(p == 8'h4a, \"struct fields\");\n        k = 8'd3;\n        $assert(r == 4'd3, \"clamp pass-through\");\n        $assert(m == 16'd543, \"multiply 2\");\n        $assert(p.lo == 4'h5, \"struct field read\");\n        k = 8'd0;\n        $assert(r == 4'd1, \"clamp zero\");\n        $finish();\n    }\n}\n\n#[test(test_ranges)]\nmodule TestRanges {\n    var v : logic<6>;\n    var cl: logic<2>;\n    var rv: logic<6>;\n\n    inst u: Ranges (\n        i_v : v ,\n        o_cl: cl,\n        o_rv: rv,\n    );\n\n    initial {\n        v = 6'd0;\n        $assert(cl == 2'd0, \"0 in 0..10\");\n        $assert(rv == 6'h2a, \"reverse, odd bits inverted (0)\");\n        v = 6'd9;\n        $assert(cl == 2'd0, \"9 in 0..10\");\n        v = 6'd10;\n        $assert(cl == 2'd1, \"10 in 10..=20\");\n        v = 6'd20;\n        $assert(cl == 2'd1, \"20 in 10..=20\");\n        v = 6'd22;\n        $assert(cl == 2'd2, \"22 listed\");\n        v = 6'd23;\n        $assert(cl == 2'd3, \"23 default\");\n        v = 6'h3f;\n        $assert(rv == 6'h15, \"reverse, odd bits inverted (all ones)\");\n        v = 6'h20;\n        $assert(rv == 6'h2b, \"reverse, odd bits inverted (msb)\");\n        $finish();\n    }\n}\n\n#[test(test_counters)]\nmodule TestCounters {\n    inst clk: $tb::clock_gen;\n\n    var rst: reset_sync_high;\n    var en : logic;\n    var a  : logic<4>;\n    var b  : logic<4>;\n\n    inst u: Top (\n        i_clk: clk,\n        i_rst: rst,\n        i_en : en ,\n        o_a  : a  ,\n        o_b  : b  ,\n    );\n\n    initial {\n        rst = 1;\n        en  = 1;\n        clk.next(2);\n        $assert(a == 4'd3, \"c0 reset value (INIT = 3)\");\n        $assert(b == 4'd5, \"c1 reset value (INIT = 5)\");\n        rst = 0;\n        clk.next(4);\n        $assert(a == 4'd7, \"c0 counts while enabled\");\n        $assert(b == 4'd5, \"c1 holds while disabled\");\n        en = 0;\n        clk.next(3);\n        $assert(a == 4'd7, \"c0 holds\");\n        $assert(b == 4'd8, \"c1 counts\");\n        $finish();\n    }\n}\n"}],"synth":"Top","title_en":"features: shifts / functions / ranges / counters","group_en":"Combined"},{"id":"bram","group":"綜合","title":"BramMix：4 個 block RAM + 邏輯","files":[{"name":"sync_ram.veryl","src":"// ==========================================\n// 同步讀取 RAM：讀取位址在時脈正緣取樣，下一拍才有資料\n// （iCE40 block RAM 的行為：合成到 FPGA 時會變成 SB_RAM40_4K）\n// ==========================================\nmodule SyncRam #(\n    param ADDR_W: u32 = 9,\n    param DATA_W: u32 = 8,\n) (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<ADDR_W>,\n    i_wdata: input  logic<DATA_W>,\n    i_re   : input  logic,\n    i_raddr: input  logic<ADDR_W>,\n    o_rdata: output logic<DATA_W>,\n) {\n    var mem: logic<DATA_W> [1 << ADDR_W];\n\n    always_ff (i_clk) {\n        if i_we {\n            mem[i_waddr] = i_wdata;\n        }\n        if i_re {\n            o_rdata = mem[i_raddr];\n        }\n    }\n}\n\n#[test(sync_ram_test)]\nmodule TestSyncRam {\n    inst clk: $tb::clock_gen;\n\n    var we   : logic;\n    var waddr: logic<9>;\n    var wdata: logic<8>;\n    var re   : logic;\n    var raddr: logic<9>;\n    var rdata: logic<8>;\n\n    inst u: SyncRam (\n        i_clk  : clk,\n        i_we   : we,\n        i_waddr: waddr,\n        i_wdata: wdata,\n        i_re   : re,\n        i_raddr: raddr,\n        o_rdata: rdata,\n    );\n\n    initial {\n        re = 1;\n        we = 1;\n        waddr = 9'd5;   wdata = 8'h5A; clk.next();\n        waddr = 9'd300; wdata = 8'hC3; clk.next();\n        waddr = 9'd511; wdata = 8'h7E; clk.next();\n        we = 0;\n\n        // 讀取：下一拍才出現\n        raddr = 9'd300; clk.next();\n        $assert(rdata == 8'hC3, \"read 300\");\n        raddr = 9'd5;   clk.next();\n        $assert(rdata == 8'h5A, \"read 5\");\n        raddr = 9'd511; clk.next();\n        $assert(rdata == 8'h7E, \"read 511\");\n\n        // 讀取致能關閉時輸出保持\n        re = 0;\n        raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h7E, \"hold when re = 0\");\n\n        // 同一拍讀寫同一位址：讀到舊值\n        re = 1;\n        we = 1;\n        waddr = 9'd5; wdata = 8'h11; raddr = 9'd5; clk.next();\n        $assert(rdata == 8'h5A, \"read-during-write returns the old value\");\n        we = 0;\n        clk.next();\n        $assert(rdata == 8'h11, \"new value next cycle\");\n        $finish();\n    }\n}\n"},{"name":"bram_tests.veryl","src":"// Block RAM inference tests: SyncRam (examples/src/sync_ram.veryl) in every\n// iCE40 RAM mode, a word wider than one block, and two read ports.\n\nmodule Bram256x16 (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<8>,\n    i_wdata: input  logic<16>,\n    i_re   : input  logic,\n    i_raddr: input  logic<8>,\n    o_rdata: output logic<16>,\n) {\n    inst u: SyncRam #(ADDR_W: 8, DATA_W: 16) (\n        i_clk,\n        i_we,\n        i_waddr,\n        i_wdata,\n        i_re,\n        i_raddr,\n        o_rdata,\n    );\n}\n\nmodule Bram1024x4 (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<10>,\n    i_wdata: input  logic<4>,\n    i_re   : input  logic,\n    i_raddr: input  logic<10>,\n    o_rdata: output logic<4>,\n) {\n    inst u: SyncRam #(ADDR_W: 10, DATA_W: 4) (\n        i_clk,\n        i_we,\n        i_waddr,\n        i_wdata,\n        i_re,\n        i_raddr,\n        o_rdata,\n    );\n}\n\nmodule Bram2048x2 (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<11>,\n    i_wdata: input  logic<2>,\n    i_re   : input  logic,\n    i_raddr: input  logic<11>,\n    o_rdata: output logic<2>,\n) {\n    inst u: SyncRam #(ADDR_W: 11, DATA_W: 2) (\n        i_clk,\n        i_we,\n        i_waddr,\n        i_wdata,\n        i_re,\n        i_raddr,\n        o_rdata,\n    );\n}\n\nmodule Bram512x20 (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<9>,\n    i_wdata: input  logic<20>,\n    i_re   : input  logic,\n    i_raddr: input  logic<9>,\n    o_rdata: output logic<20>,\n) {\n    inst u: SyncRam #(ADDR_W: 9, DATA_W: 20) (\n        i_clk,\n        i_we,\n        i_waddr,\n        i_wdata,\n        i_re,\n        i_raddr,\n        o_rdata,\n    );\n}\n\n// two synchronous read ports: one block RAM copy per port\nmodule Bram2Read (\n    i_clk  : input  clock,\n    i_we   : input  logic,\n    i_waddr: input  logic<8>,\n    i_wdata: input  logic<16>,\n    i_re   : input  logic,\n    i_raddr: input  logic<8>,\n    i_raddr2: input logic<8>,\n    o_rdata: output logic<16>,\n    o_rdata2: output logic<16>,\n) {\n    var mem: logic<16> [256];\n\n    always_ff (i_clk) {\n        if i_we {\n            mem[i_waddr] = i_wdata;\n        }\n        if i_re {\n            o_rdata = mem[i_raddr];\n        }\n        o_rdata2 = mem[i_raddr2];\n    }\n}\n\n// block RAMs inside logic, few IO pins (for place & route): a 256 x 32\n// memory (two blocks side by side) written with a pattern every cycle and\n// read by two ports (two more blocks)\nmodule BramMix (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    i_sel: input  logic<2>,\n    o_out: output logic<8>,\n) {\n    var mem: logic<32> [256];\n    var wa : logic<8>;\n    var ra : logic<8>;\n    var rb : logic<8>;\n    var qa : logic<32>;\n    var qb : logic<32>;\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            wa = 0;\n            ra = 0;\n            rb = 0;\n        } else {\n            wa = wa + 8'd1;\n            ra = wa - 8'd3;\n            rb = ~wa;\n        }\n    }\n\n    always_ff (i_clk) {\n        mem[wa] = {wa, wa ^ 8'h5a, ~wa, wa + 8'd7};\n        qa      = mem[ra];\n        qb      = mem[rb];\n    }\n\n    always_comb {\n        case i_sel {\n            2'd0   : o_out = qa[7:0] ^ qb[31:24];\n            2'd1   : o_out = qa[15:8] + qb[7:0];\n            2'd2   : o_out = qa[23:16];\n            default: o_out = qb[15:8];\n        }\n    }\n}\n\n#[test(bram_mix_test)]\nmodule TestBramMix {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var sel: logic<2>;\n    var out: logic<8>;\n\n    inst u: BramMix (\n        i_clk: clk,\n        i_rst: rst,\n        i_sel: sel,\n        o_out: out,\n    );\n\n    initial {\n        sel = 2'd2;\n        rst.assert();\n        // port A reads the word written 4 cycles earlier: qa[23:16] = ~address\n        clk.next(20);\n        $assert(out == 8'h55, \"sel 2 after 20 cycles\");\n        // after a full pass every word is written\n        clk.next(300);\n        $assert(out == 8'h61, \"sel 2: ~address of port A\");\n        sel = 2'd3;\n        $assert(out == 8'h3e, \"sel 3: address of port B ^ 8'h5a\");\n        sel = 2'd0;\n        $assert(out == 8'h83, \"sel 0\");\n        sel = 2'd1;\n        $assert(out == 8'h8c, \"sel 1\");\n        $finish();\n    }\n}\n"}],"synth":"BramMix","title_en":"BramMix: 4 block RAMs + logic","group_en":"Combined"},{"id":"lang","group":"綜合","title":"lang：除法、interface、200 位元、雙時脈","files":[{"name":"lang.veryl","src":"// Language features beyond the basics: non-constant division / remainder\n// (unsigned and signed) and interfaces with modports.\n\nmodule Div (\n    i_a : input  logic<8>,\n    i_b : input  logic<8>,\n    o_q : output logic<8>,\n    o_r : output logic<8>,\n    o_sq: output logic<8>,\n    o_sr: output logic<8>,\n) {\n    assign o_q  = i_a / i_b;\n    assign o_r  = i_a % i_b;\n    assign o_sq = $signed(i_a) / $signed(i_b);\n    assign o_sr = $signed(i_a) % $signed(i_b);\n}\n\n#[test(div_test)]\nmodule TestDiv {\n    var a : logic<8>;\n    var b : logic<8>;\n    var q : logic<8>;\n    var r : logic<8>;\n    var sq: logic<8>;\n    var sr: logic<8>;\n\n    inst u: Div (\n        i_a : a,\n        i_b : b,\n        o_q : q,\n        o_r : r,\n        o_sq: sq,\n        o_sr: sr,\n    );\n\n    initial {\n        a = 8'd200;\n        b = 8'd7;\n        $assert(q == 8'd28, \"200 / 7\");\n        $assert(r == 8'd4, \"200 % 7\");\n        a = 8'hF6; // -10\n        b = 8'd3;\n        $assert(sq == 8'hFD, \"-10 / 3 = -3\");\n        $assert(sr == 8'hFF, \"-10 % 3 = -1\");\n        $finish();\n    }\n}\n\n// a valid / ready handshake as an interface; `fire` is computed inside the\n// interface, the monitor modport is \"everything an input\" (..input)\ninterface Handshake #(\n    param W: u32 = 8,\n) {\n    var valid: logic;\n    var ready: logic;\n    var data : logic<W>;\n    let fire : logic = valid && ready;\n\n    modport source {\n        valid: output,\n        data : output,\n        ready: input,\n        fire : input,\n    }\n\n    modport sink {\n        valid: input,\n        data : input,\n        ready: output,\n        fire : input,\n    }\n\n    modport monitor {\n        ..input\n    }\n}\n\nmodule HsSource (\n    i_clk: input clock,\n    i_rst: input reset,\n    hs   : modport Handshake::source,\n) {\n    var cnt: logic<8>;\n\n    always_ff {\n        if_reset {\n            cnt = 8'd1;\n        } else if hs.fire {\n            cnt = cnt + 8'd3;\n        }\n    }\n\n    assign hs.valid = 1'b1;\n    assign hs.data  = cnt;\n}\n\nmodule HsSink (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    hs   : modport Handshake::sink,\n    o_sum: output logic<16>,\n) {\n    var sum: logic<16>;\n    var rdy: logic;\n\n    always_ff {\n        if_reset {\n            sum = 0;\n            rdy = 0;\n        } else {\n            rdy = ~rdy;\n            if hs.fire {\n                sum = sum + {8'd0, hs.data};\n            }\n        }\n    }\n\n    assign hs.ready = rdy;\n    assign o_sum    = sum;\n}\n\nmodule HsTop (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    o_sum: output logic<16>,\n) {\n    inst h  : Handshake;\n    inst src: HsSource (\n        i_clk,\n        i_rst,\n        hs   : h,\n    );\n    inst snk: HsSink (\n        i_clk,\n        i_rst,\n        hs   : h,\n        o_sum,\n    );\n}\n\n#[test(hs_test)]\nmodule TestHs {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var sum: logic<16>;\n\n    inst u: HsTop (\n        i_clk: clk,\n        i_rst: rst,\n        o_sum: sum,\n    );\n\n    initial {\n        rst.assert();\n        clk.next(20);\n        // 1 + 4 + 7 + ... over the cycles the sink is ready (iverilog agrees;\n        // veryl 0.22's own simulator reads 0 here, it mishandles interfaces)\n        $assert(sum == 16'd145, \"handshake sum\");\n        $finish();\n    }\n}\n\n// wider than 128 bits: a 200-bit adder and shifter\nmodule Wide (\n    i_a: input  logic<200>,\n    i_b: input  logic<200>,\n    o_s: output logic<200>,\n    o_x: output logic<200>,\n    o_c: output logic,\n) {\n    var sum: logic<201>;\n\n    assign sum = {1'b0, i_a} + {1'b0, i_b};\n    assign o_s = sum[199:0];\n    assign o_c = sum[200];\n    assign o_x = i_a ^ (i_b << 150);\n}\n\n#[test(wide_test)]\nmodule TestWide {\n    var a: logic<200>;\n    var b: logic<200>;\n    var s: logic<200>;\n    var x: logic<200>;\n    var c: logic;\n\n    inst u: Wide (\n        i_a: a,\n        i_b: b,\n        o_s: s,\n        o_x: x,\n        o_c: c,\n    );\n\n    initial {\n        // a carry rippling through all 200 bits\n        a = ~200'd0;\n        b = 200'd1;\n        $assert(s == 200'd0, \"wrap to zero\");\n        $assert(c == 1'b1, \"carry out of bit 199\");\n        // a carry across the 128-bit boundary\n        a = 200'h0_0000_0000_0000_0000_FFFF_FFFF_FFFF_FFFF_FFFF_FFFF_FFFF_FFFF;\n        b = 200'd1;\n        $assert(s[128] == 1'b1, \"carry into bit 128\");\n        $assert(s[127:0] == 128'd0, \"low half zero\");\n        // shift past bit 128\n        a = 200'd0;\n        b = 200'd5;\n        $assert(x[150] == 1'b1 && x[151] == 1'b0 && x[152] == 1'b1, \"shifted to bit 150\");\n        $assert(x[199:153] == 47'd0, \"nothing above\");\n        $finish();\n    }\n}\n\n// two clock domains and a negative-edge flip-flop (each domain annotated\n// with its own clock and reset, as Veryl requires)\nmodule TwoClk (\n    i_clka: input  'a clock        ,\n    i_rsta: input  'a reset        ,\n    i_clkb: input  'b clock        ,\n    i_rstb: input  'b reset        ,\n    i_clkn: input  'c clock_negedge,\n    i_rstn: input  'c reset        ,\n    o_a   : output 'a logic<8>     ,\n    o_b   : output 'b logic<8>     ,\n    o_n   : output 'c logic<8>     ,\n) {\n    var ca: 'a logic<8>;\n    var cb: 'b logic<8>;\n    var cn: 'c logic<8>;\n\n    always_ff (i_clka, i_rsta) {\n        if_reset {\n            ca = 0;\n        } else {\n            ca = ca + 8'd1;\n        }\n    }\n\n    always_ff (i_clkb, i_rstb) {\n        if_reset {\n            cb = 0;\n        } else {\n            cb = cb + 8'd2;\n        }\n    }\n\n    always_ff (i_clkn, i_rstn) {\n        if_reset {\n            cn = 0;\n        } else {\n            cn = cn + 8'd3;\n        }\n    }\n\n    assign o_a = ca;\n    assign o_b = cb;\n    assign o_n = cn;\n}\n"}],"synth":"HsTop","title_en":"lang: division, interface, 200 bits, two clocks","group_en":"Combined"},{"id":"acc","group":"綜合","title":"AccTest 32-bit 進位鏈","files":[{"name":"pnr_tests.veryl","src":"// Place-and-route stress designs with few pins (they must fit the 39 IOs\n// of the SG48 package): long carry chains crossing tiles, carry-in from a\n// signal (feed-in), carry-out used as logic (feed-out, comparators).\n\nmodule AccTest (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    i_d  : input  logic<8>,\n    i_ci : input  logic,\n    i_sel: input  logic<2>,\n    o_q  : output logic<8>,\n    o_lt : output logic,\n    o_ltu: output logic,\n    o_eq : output logic,\n) {\n    var acc: logic<32>;\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            acc = 32'd0;\n        } else {\n            case i_sel {\n                2'd0   : acc = acc + {i_d repeat 4} + {31'd0, i_ci};\n                2'd1   : acc = acc - {24'd0, i_d};\n                2'd2   : acc = acc ^ (acc << 3) ^ {24'd0, i_d};\n                default: acc = acc + 32'd1;\n            }\n        }\n    }\n\n    assign o_q   = acc[31:24] ^ acc[23:16] ^ acc[15:8] ^ acc[7:0];\n    assign o_lt  = $signed(acc) <: $signed({i_d repeat 4});\n    assign o_ltu = acc <: {i_d repeat 4};\n    assign o_eq  = acc[15:0] == {i_d, i_d};\n}\n\n#[test(test_acc)]\nmodule TestAccTest {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var d  : logic<8>;\n    var ci : logic;\n    var sel: logic<2>;\n    var q  : logic<8>;\n    var lt : logic;\n    var ltu: logic;\n    var eq : logic;\n\n    inst u: AccTest (\n        i_clk: clk,\n        i_rst: rst,\n        i_d  : d  ,\n        i_ci : ci ,\n        i_sel: sel,\n        o_q  : q  ,\n        o_lt : lt ,\n        o_ltu: ltu,\n        o_eq : eq ,\n    );\n\n    initial {\n        d   = 8'h01;\n        ci  = 1'b1;\n        sel = 2'd0;\n        rst.assert();\n        clk.next(1);\n        // acc = 0x01010101 + 1 = 0x01010102\n        $assert(q == 8'h03, \"xor of bytes 01^01^01^02\");\n        sel = 2'd1;\n        d   = 8'h03;\n        clk.next(1);\n        // acc = 0x010100ff\n        $assert(q == 8'hff, \"after subtract\");\n        $assert(ltu == 1'b1, \"0x010100ff < 0x03030303 unsigned\");\n        $assert(lt == 1'b1, \"0x010100ff < 0x03030303 signed\");\n        $assert(eq == 1'b0, \"low half differs\");\n        $finish();\n    }\n}\n"}],"synth":"AccTest","title_en":"AccTest 32-bit carry chain","group_en":"Combined"},{"id":"uart","group":"周邊","title":"UART 收發器（迴路測試）","files":[{"name":"uart.veryl","src":"// ==========================================\n// UART：8N1 傳送器與接收器（每個位元 CLKS_PER_BIT 個時脈）\n// ==========================================\nmodule UartTx #(\n    param CLKS_PER_BIT: u32 = 16,\n) (\n    i_clk  : input  clock    ,\n    i_rst  : input  reset    ,\n    i_valid: input  logic    ,\n    i_data : input  logic<8> ,\n    o_ready: output logic    ,\n    o_tx   : output logic    ,\n) {\n    var busy : logic    ;\n    var shift: logic<10>; // stop, data[7:0], start (LSB first)\n    var nbits: logic<4> ;\n    var cnt  : logic<16>;\n\n    always_ff {\n        if_reset {\n            busy  = 0;\n            shift = 10'h3ff;\n            nbits = 0;\n            cnt   = 0;\n        } else if !busy {\n            if i_valid {\n                busy  = 1;\n                shift = {1'b1, i_data, 1'b0};\n                nbits = 4'd10;\n                cnt   = 0;\n            }\n        } else if cnt == CLKS_PER_BIT - 1 {\n            cnt   = 0;\n            shift = {1'b1, shift[9:1]};\n            nbits = nbits - 4'd1;\n            if nbits == 4'd1 {\n                busy = 0;\n            }\n        } else {\n            cnt = cnt + 16'd1;\n        }\n    }\n\n    assign o_ready = !busy;\n    assign o_tx    = shift[0];\n}\n\nmodule UartRx #(\n    param CLKS_PER_BIT: u32 = 16,\n) (\n    i_clk  : input  clock   ,\n    i_rst  : input  reset   ,\n    i_rx   : input  logic   ,\n    o_valid: output logic   ,\n    o_data : output logic<8>,\n) {\n    var busy : logic    ;\n    var cnt  : logic<16>;\n    var nbits: logic<4> ;\n    var data : logic<8> ;\n    var valid: logic    ;\n\n    always_ff {\n        if_reset {\n            busy  = 0;\n            cnt   = 0;\n            nbits = 0;\n            data  = 0;\n            valid = 0;\n        } else {\n            valid = 0;\n            if !busy {\n                // start bit: wait half a bit, then sample in the middle\n                if !i_rx {\n                    busy  = 1;\n                    cnt   = CLKS_PER_BIT / 2;\n                    nbits = 0;\n                }\n            } else if cnt == CLKS_PER_BIT - 1 {\n                cnt = 0;\n                if nbits == 4'd9 {\n                    busy  = 0;\n                    valid = i_rx; // stop bit must be 1\n                } else {\n                    if nbits != 4'd0 {\n                        data = {i_rx, data[7:1]};\n                    }\n                    nbits = nbits + 4'd1;\n                }\n            } else {\n                cnt = cnt + 16'd1;\n            }\n        }\n    }\n\n    assign o_valid = valid;\n    assign o_data  = data;\n}\n\n// loopback: what the transmitter sends, the receiver gets back\nmodule UartLoop (\n    i_clk  : input  clock   ,\n    i_rst  : input  reset   ,\n    i_valid: input  logic   ,\n    i_data : input  logic<8>,\n    o_ready: output logic   ,\n    o_tx   : output logic   ,\n    o_valid: output logic   ,\n    o_data : output logic<8>,\n) {\n    var line: logic;\n\n    inst tx: UartTx #(CLKS_PER_BIT: 8) (\n        i_clk           ,\n        i_rst           ,\n        i_valid         ,\n        i_data          ,\n        o_ready         ,\n        o_tx   : line   ,\n    );\n    inst rx: UartRx #(CLKS_PER_BIT: 8) (\n        i_clk           ,\n        i_rst           ,\n        i_rx   : line   ,\n        o_valid         ,\n        o_data          ,\n    );\n    assign o_tx = line;\n}\n\n#[test(uart_test)]\nmodule TestUart {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var valid : logic   ;\n    var data  : logic<8>;\n    var ready : logic   ;\n    var tx    : logic   ;\n    var rvalid: logic   ;\n    var rdata : logic<8>;\n\n    inst u: UartLoop (\n        i_clk  : clk   ,\n        i_rst  : rst   ,\n        i_valid: valid ,\n        i_data : data  ,\n        o_ready: ready ,\n        o_tx   : tx    ,\n        o_valid: rvalid,\n        o_data : rdata ,\n    );\n\n    initial {\n        valid = 0;\n        data  = 0;\n        rst.assert();\n        clk.next(2);\n        // one frame = 10 bits × 8 clocks; the receiver reports in the stop bit\n        valid = 1;\n        data  = 8'hA5;\n        clk.next();\n        valid = 0;\n        clk.next(85);\n        $assert(rdata == 8'hA5, \"first byte\");\n        valid = 1;\n        data  = 8'h3C;\n        clk.next();\n        valid = 0;\n        clk.next(85);\n        $assert(rdata == 8'h3C, \"second byte\");\n        $finish();\n    }\n}\n"}],"synth":"UartLoop","note":"UartTx → UartRx 迴路，8N1，每位元 8 個時脈","title_en":"UART transmitter / receiver (loopback test)","note_en":"UartTx → UartRx loopback, 8N1, 8 clocks per bit","group_en":"Peripherals"},{"id":"vga","group":"周邊","title":"VGA 640×480 時序 + 色條","files":[{"name":"vga.veryl","src":"// ==========================================\n// VGA 時序產生器，預設 640×480 @ 60 Hz（像素時脈 25.175 MHz）：\n// 水平 640 + 16 + 96 + 48 = 800，垂直 480 + 10 + 2 + 33 = 525；\n// hsync / vsync 低態有效，輸出 8 條色帶的 3-bit RGB 圖樣\n// ==========================================\nmodule VgaTiming #(\n    param H_VIS : u32 = 640,\n    param H_FP  : u32 = 16 ,\n    param H_SYNC: u32 = 96 ,\n    param H_BP  : u32 = 48 ,\n    param V_VIS : u32 = 480,\n    param V_FP  : u32 = 10 ,\n    param V_SYNC: u32 = 2  ,\n    param V_BP  : u32 = 33 ,\n) (\n    i_clk  : input  clock    ,\n    i_rst  : input  reset    ,\n    o_hsync: output logic    ,\n    o_vsync: output logic    ,\n    o_video: output logic    ,\n    o_x    : output logic<10>,\n    o_y    : output logic<10>,\n    o_rgb  : output logic<3> ,\n) {\n    const H_TOTAL: u32 = H_VIS + H_FP + H_SYNC + H_BP;\n    const V_TOTAL: u32 = V_VIS + V_FP + V_SYNC + V_BP;\n\n    var x: logic<10>;\n    var y: logic<10>;\n\n    always_ff {\n        if_reset {\n            x = 0;\n            y = 0;\n        } else if x == H_TOTAL - 1 {\n            x = 0;\n            y = if y == V_TOTAL - 1 ? 0 : y + 1;\n        } else {\n            x = x + 1;\n        }\n    }\n\n    assign o_x     = x;\n    assign o_y     = y;\n    assign o_video = (x <: H_VIS) && (y <: V_VIS);\n    assign o_hsync = !((x >= H_VIS + H_FP) && (x <: H_VIS + H_FP + H_SYNC));\n    assign o_vsync = !((y >= V_VIS + V_FP) && (y <: V_VIS + V_FP + V_SYNC));\n    // eight vertical color bars, 80 pixels each at 640 wide\n    assign o_rgb = if o_video ? x[9:7] ^ {2'b0, x[6]} : 3'd0;\n}\n\n// 縮小版畫面（16×8，總共 24×12）以便快速模擬；合成時用預設的 640×480\n#[test(vga_test)]\nmodule TestVga {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var hs : logic    ;\n    var vs : logic    ;\n    var vid: logic    ;\n    var x  : logic<10>;\n    var y  : logic<10>;\n    var rgb: logic<3> ;\n\n    inst u: VgaTiming #(\n        H_VIS : 16,\n        H_FP  : 2 ,\n        H_SYNC: 4 ,\n        H_BP  : 2 ,\n        V_VIS : 8 ,\n        V_FP  : 1 ,\n        V_SYNC: 1 ,\n        V_BP  : 2 ,\n    ) (\n        i_clk  : clk,\n        i_rst  : rst,\n        o_hsync: hs ,\n        o_vsync: vs ,\n        o_video: vid,\n        o_x    : x  ,\n        o_y    : y  ,\n        o_rgb  : rgb,\n    );\n\n    initial {\n        rst.assert();\n        $assert(vid == 1'b1 && hs == 1'b1, \"first pixel visible\");\n        clk.next(16);\n        $assert(vid == 1'b0 && hs == 1'b1, \"front porch\");\n        clk.next(2);\n        $assert(x == 10'd18 && hs == 1'b0, \"hsync starts after the front porch\");\n        clk.next(4);\n        $assert(hs == 1'b1, \"hsync is 4 pixels\");\n        clk.next(2);\n        $assert(x == 10'd0 && y == 10'd1, \"next line after 24\");\n        clk.next(24 * 8);\n        $assert(y == 10'd9 && vs == 1'b0 && vid == 1'b0, \"vsync on line 9\");\n        clk.next(24 * 3);\n        $assert(x == 10'd0 && y == 10'd0 && vs == 1'b1, \"frame of 12 lines\");\n        $finish();\n    }\n}\n"}],"synth":"VgaTiming","note":"測試用縮小的 24×12 畫面；合成用預設的 800×525","title_en":"VGA 640×480 timing + color bars","note_en":"The test uses a small 24×12 frame; synthesis uses the default 800×525","group_en":"Peripherals"},{"id":"rv32i","group":"RISC-V","title":"RV32I 單週期 CPU","files":[{"name":"rv32i.veryl","src":"// ==========================================\n// 1. 定義常數與列舉\n// ==========================================\npackage RiscvTypes {\n    enum AluOp: logic<4> {\n        Add,\n        Sub,\n        And,\n        Or,\n        Slt,\n        Sltu,\n        Xor,\n        Sll,\n        Srl,\n        Sra,\n    }\n\n    enum Opcode: logic<7> {\n        RType  = 7'b0110011,\n        IType  = 7'b0010011,\n        Load   = 7'b0000011,\n        Store  = 7'b0100011,\n        Branch = 7'b1100011,\n        Jal    = 7'b1101111,\n        Jalr   = 7'b1100111,\n        Lui    = 7'b0110111,\n        Auipc  = 7'b0010111,\n    }\n}\n\n// ==========================================\n// 2. 算術邏輯單元（ALU）\n// ==========================================\nmodule Alu (\n    i_op : input  RiscvTypes::AluOp,\n    i_a  : input  logic<32>,\n    i_b  : input  logic<32>,\n    o_res: output logic<32>,\n) {\n    import RiscvTypes::*;\n\n    always_comb {\n        case i_op {\n            AluOp::Add : o_res = i_a + i_b;\n            AluOp::Sub : o_res = i_a - i_b;\n            AluOp::And : o_res = i_a & i_b;\n            AluOp::Or  : o_res = i_a | i_b;\n            AluOp::Xor : o_res = i_a ^ i_b;\n            AluOp::Slt : o_res = {31'd0, $signed(i_a) <: $signed(i_b)};\n            AluOp::Sltu: o_res = {31'd0, i_a <: i_b};\n            // 移位量只取 i_b 的低 5 bit\n            AluOp::Sll: o_res = i_a << i_b[4:0];\n            AluOp::Srl: o_res = i_a >> i_b[4:0];\n            AluOp::Sra: o_res = $signed(i_a) >>> i_b[4:0];\n            default   : o_res = 32'd0;\n        }\n    }\n}\n\n// ==========================================\n// 3. 通用暫存器堆（Register File）\n// ==========================================\nmodule RegFile (\n    i_clk    : input  clock,\n    i_rst    : input  reset,\n    i_rs1_idx: input  logic<5>,\n    i_rs2_idx: input  logic<5>,\n    i_rd_idx : input  logic<5>,\n    i_rd_data: input  logic<32>,\n    i_rd_we  : input  logic,\n    o_rs1_val: output logic<32>,\n    o_rs2_val: output logic<32>,\n) {\n    var rf: logic<32> [32];\n\n    #[allow(missing_reset_statement)]\n    always_ff (i_clk, i_rst) {\n        if_reset {\n        } else if (i_rd_we && (i_rd_idx != 5'd0)) {\n            rf[i_rd_idx] = i_rd_data;\n        }\n    }\n\n    always_comb {\n        if i_rs1_idx == 5'd0 {\n            o_rs1_val = 32'd0;\n        } else {\n            o_rs1_val = rf[i_rs1_idx];\n        }\n\n        if i_rs2_idx == 5'd0 {\n            o_rs2_val = 32'd0;\n        } else {\n            o_rs2_val = rf[i_rs2_idx];\n        }\n    }\n}\n\n// ==========================================\n// 4. CPU 頂層模組（單週期 RV32I，不含 fence/ecall/ebreak/CSR）\n// ==========================================\n// 資料記憶體介面：o_dmem_addr 為位元組位址；寫入時 o_dmem_wdata 已對齊到\n// 32 bit 字中的位置，o_dmem_wstrb 指出要寫的位元組；讀取時 i_dmem_rdata\n// 是 o_dmem_addr 所在的整個字（由 CPU 取出 byte/halfword 並做符號擴展）。\nmodule RiscvCore (\n    i_clk       : input  clock,\n    i_rst       : input  reset,\n    o_imem_addr : output logic<32>,\n    i_imem_inst : input  logic<32>,\n    o_dmem_addr : output logic<32>,\n    o_dmem_wdata: output logic<32>,\n    o_dmem_wstrb: output logic<4>,\n    i_dmem_rdata: input  logic<32>,\n    o_dmem_we   : output logic,\n) {\n    import RiscvTypes::*;\n\n    var pc        : logic<32>;\n    var next_pc   : logic<32>;\n    var pc_plus_4 : logic<32>;\n    var branch_tgt: logic<32>;\n\n    var rs1_data  : logic<32>;\n    var rs2_data  : logic<32>;\n    var alu_src_b : logic<32>;\n    var alu_out   : logic<32>;\n    var imm       : logic<32>;\n    var wb_data   : logic<32>;\n    var load_data : logic<32>;\n    var store_data: logic<32>;\n    var store_strb: logic<4>;\n    var take      : logic;\n\n    var alu_op    : AluOp;\n    var arith_op  : AluOp;\n    var reg_write : logic;\n    var dmem_write: logic;\n\n    let opcode : logic<7> = i_imem_inst[6:0];\n    let rd_idx : logic<5> = i_imem_inst[11:7];\n    let funct3 : logic<3> = i_imem_inst[14:12];\n    let rs1_idx: logic<5> = i_imem_inst[19:15];\n    let rs2_idx: logic<5> = i_imem_inst[24:20];\n    let funct7 : logic<7> = i_imem_inst[31:25];\n\n    // --- 立即數解碼 ---\n    always_comb {\n        case opcode {\n            Opcode::IType, Opcode::Load, Opcode::Jalr:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:20]};\n            Opcode::Store:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:25], i_imem_inst[11:7]};\n            Opcode::Branch:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[7], i_imem_inst[30:25], i_imem_inst[11:8], 1'b0};\n            Opcode::Jal:\n                imm = {i_imem_inst[31] repeat 12, i_imem_inst[19:12], i_imem_inst[20], i_imem_inst[30:21], 1'b0};\n            Opcode::Lui, Opcode::Auipc:\n                imm = {i_imem_inst[31:12], 12'd0};\n            default:\n                imm = 32'd0;\n        }\n    }\n\n    // --- 控制邏輯 ---\n    // funct7[5] 選 sub / sra；I-type 只有 srai 使用（addi 沒有減法版本）\n    let alt: logic = funct7[5] && (opcode == Opcode::RType || funct3 == 3'b101);\n\n    always_comb {\n        case funct3 {\n            3'b000 : arith_op = if alt ? AluOp::Sub : AluOp::Add;\n            3'b001 : arith_op = AluOp::Sll;\n            3'b010 : arith_op = AluOp::Slt;\n            3'b011 : arith_op = AluOp::Sltu;\n            3'b100 : arith_op = AluOp::Xor;\n            3'b101 : arith_op = if alt ? AluOp::Sra : AluOp::Srl;\n            3'b110 : arith_op = AluOp::Or;\n            default: arith_op = AluOp::And;\n        }\n    }\n\n    always_comb {\n        reg_write  = 1'b0;\n        dmem_write = 1'b0;\n        alu_op     = AluOp::Add;\n\n        case opcode {\n            Opcode::RType, Opcode::IType: {\n                reg_write = 1'b1;\n                alu_op    = arith_op;\n            }\n            Opcode::Load, Opcode::Jal, Opcode::Jalr, Opcode::Lui, Opcode::Auipc: {\n                reg_write = 1'b1;\n            }\n            Opcode::Store: {\n                dmem_write = 1'b1;\n            }\n            default: {}\n        }\n    }\n\n    // --- 分支條件（獨立的比較器，不經過 ALU）---\n    always_comb {\n        case funct3 {\n            3'b000 : take = rs1_data == rs2_data;                     // beq\n            3'b001 : take = rs1_data != rs2_data;                     // bne\n            3'b100 : take = $signed(rs1_data) <: $signed(rs2_data);   // blt\n            3'b101 : take = $signed(rs1_data) >= $signed(rs2_data);   // bge\n            3'b110 : take = rs1_data <: rs2_data;                     // bltu\n            3'b111 : take = rs1_data >= rs2_data;                     // bgeu\n            default: take = 1'b0;\n        }\n    }\n\n    // --- 載入：從整個字取出 byte / halfword ---\n    let byte_off : logic<2>  = alu_out[1:0];\n    let load_word: logic<32> = i_dmem_rdata >> {byte_off, 3'b000};\n\n    always_comb {\n        case funct3 {\n            3'b000 : load_data = {load_word[7] repeat 24, load_word[7:0]};   // lb\n            3'b001 : load_data = {load_word[15] repeat 16, load_word[15:0]}; // lh\n            3'b100 : load_data = {24'd0, load_word[7:0]};                    // lbu\n            3'b101 : load_data = {16'd0, load_word[15:0]};                   // lhu\n            default: load_data = load_word;                                  // lw\n        }\n    }\n\n    // --- 儲存：把資料複製到每個位元組位置，並產生 byte strobe ---\n    always_comb {\n        case funct3 {\n            3'b000: {\n                store_data = {rs2_data[7:0] repeat 4};\n                store_strb = 4'b0001 << byte_off;\n            }\n            3'b001: {\n                store_data = {rs2_data[15:0] repeat 2};\n                store_strb = 4'b0011 << byte_off;\n            }\n            default: {\n                store_data = rs2_data;\n                store_strb = 4'b1111;\n            }\n        }\n    }\n\n    // --- 多工器選擇 ---\n    always_comb {\n        if (opcode == Opcode::RType || opcode == Opcode::Branch) {\n            alu_src_b = rs2_data;\n        } else {\n            alu_src_b = imm;\n        }\n\n        case opcode {\n            Opcode::Load            : wb_data = load_data;\n            Opcode::Jal, Opcode::Jalr: wb_data = pc_plus_4;\n            Opcode::Lui             : wb_data = imm;\n            Opcode::Auipc           : wb_data = branch_tgt;\n            default                 : wb_data = alu_out;\n        }\n    }\n\n    // --- 模組例化 ---\n    inst u_rf: RegFile (\n        i_clk    : i_clk,\n        i_rst    : i_rst,\n        i_rs1_idx: rs1_idx,\n        i_rs2_idx: rs2_idx,\n        i_rd_idx : rd_idx,\n        i_rd_data: wb_data,\n        i_rd_we  : reg_write,\n        o_rs1_val: rs1_data,\n        o_rs2_val: rs2_data,\n    );\n\n    inst u_alu: Alu (\n        i_op : alu_op,\n        i_a  : rs1_data,\n        i_b  : alu_src_b,\n        o_res: alu_out,\n    );\n\n    // --- PC 計算 ---\n    assign pc_plus_4  = pc + 32'd4;\n    assign branch_tgt = pc + imm;\n\n    always_comb {\n        case opcode {\n            Opcode::Jal   : next_pc = branch_tgt;\n            Opcode::Jalr  : next_pc = {alu_out[31:1], 1'b0}; // (rs1 + imm) & ~1\n            Opcode::Branch: next_pc = if take ? branch_tgt : pc_plus_4;\n            default       : next_pc = pc_plus_4;\n        }\n    }\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            pc = 32'd0;\n        } else {\n            pc = next_pc;\n        }\n    }\n\n    // --- 輸出埠綁定 ---\n    assign o_imem_addr  = pc;\n    assign o_dmem_addr  = alu_out;\n    assign o_dmem_wdata = store_data;\n    assign o_dmem_wstrb = store_strb;\n    assign o_dmem_we    = dmem_write;\n}\n\n// ==========================================\n// 5. RISC-V 核心整合測試（Testbench）\n// ==========================================\n// 程式在 examples/sw/rv32i_test.S（ROM 由 examples/sw/build.sh 產生成\n// rv32i_rom.veryl），涵蓋全部 RV32I 運算指令；結果寫入 dmem[0..47]。\n#[test(test_riscv_cpu)]\nmodule TestRiscvCore {\n    // 官方 testbench 元件：clk 本身即 clock 訊號，rst 綁定 clk\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var imem_addr : logic<32>;\n    var imem_inst : logic<32>;\n    var dmem_addr : logic<32>;\n    var dmem_wdata: logic<32>;\n    var dmem_wstrb: logic<4>;\n    var dmem_rdata: logic<32>;\n    var dmem_we   : logic;\n\n    // 模擬 Data RAM：64 字（256 bytes），依 byte strobe 寫入\n    var dmem: logic<32> [64];\n\n    let wmask: logic<32> = {dmem_wstrb[3] repeat 8, dmem_wstrb[2] repeat 8, dmem_wstrb[1] repeat 8, dmem_wstrb[0] repeat 8};\n\n    #[allow(missing_reset_statement)]\n    always_ff (clk, rst) {\n        if_reset {\n        } else if dmem_we {\n            dmem[dmem_addr[7:2]] = (dmem[dmem_addr[7:2]] & ~wmask) | (dmem_wdata & wmask);\n        }\n    }\n    assign dmem_rdata = dmem[dmem_addr[7:2]];\n\n    // 程式 ROM\n    inst u_rom: RiscvTestRom (\n        i_addr: imem_addr,\n        o_inst: imem_inst,\n    );\n\n    // 例化 CPU\n    inst dut: RiscvCore (\n        i_clk       : clk,\n        i_rst       : rst,\n        o_imem_addr : imem_addr,\n        i_imem_inst : imem_inst,\n        o_dmem_addr : dmem_addr,\n        o_dmem_wdata: dmem_wdata,\n        o_dmem_wstrb: dmem_wstrb,\n        i_dmem_rdata: dmem_rdata,\n        o_dmem_we   : dmem_we,\n    );\n\n    initial {\n        // 1. 重設後釋放，開始執行\n        rst.assert();\n\n        // 2. 執行到程式結束（停在 halt 迴圈）\n        clk.next(200);\n\n        // 3. 斷言驗證（期望值與 rv32i_test.S 的註解相同）\n        $assert(dmem[47] == 32'h00000001, \"program finished\");\n        $assert(dmem[0] == 32'h12345678, \"lui + addi\");\n        $assert(dmem[1] == 32'h00000010, \"auipc\");\n        $assert(dmem[2] == 32'hffffffff, \"lui + srai\");\n        $assert(dmem[3] == 32'hfffffffb, \"add\");\n        $assert(dmem[4] == 32'h0000000b, \"sub\");\n        $assert(dmem[5] == 32'hffffffc0, \"sll\");\n        $assert(dmem[6] == 32'h1fffffff, \"srl\");\n        $assert(dmem[7] == 32'hffffffff, \"sra\");\n        $assert(dmem[8] == 32'hc0000000, \"slli\");\n        $assert(dmem[9] == 32'h0000000f, \"srli\");\n        $assert(dmem[10] == 32'hfffffffc, \"srai\");\n        $assert(dmem[11] == 32'hedcba980, \"xor\");\n        $assert(dmem[12] == 32'hfffffffc, \"xori\");\n        $assert(dmem[13] == 32'h1234567b, \"or\");\n        $assert(dmem[14] == 32'h000007f3, \"ori\");\n        $assert(dmem[15] == 32'h12345678, \"and\");\n        $assert(dmem[16] == 32'h00000078, \"andi\");\n        $assert(dmem[17] == 32'h00000001, \"slt\");\n        $assert(dmem[18] == 32'h00000000, \"sltu\");\n        $assert(dmem[19] == 32'h00000000, \"slti\");\n        $assert(dmem[20] == 32'h00000001, \"sltiu\");\n        $assert(dmem[21] == 32'h00000006, \"sll uses rs2[4:0]\");\n        $assert(dmem[22] == 32'h000000aa, \"beq/bne/blt/bge\");\n        $assert(dmem[23] == 32'h0000000a, \"bltu/bgeu\");\n        $assert(dmem[24] == 32'h0000000f, \"backward branch loop\");\n        $assert(dmem[25] == 32'h00000000, \"jal/jalr skip\");\n        $assert(dmem[26] == 32'h00000008, \"jalr link\");\n        $assert(dmem[27] == 32'hfffffffc, \"jal link\");\n        $assert(dmem[28] == 32'h00000078, \"lb\");\n        $assert(dmem[29] == 32'h00000012, \"lb offset 3\");\n        $assert(dmem[30] == 32'hfffffff8, \"lb sign\");\n        $assert(dmem[31] == 32'h000000f8, \"lbu\");\n        $assert(dmem[32] == 32'h00001234, \"lh\");\n        $assert(dmem[33] == 32'hfffffff8, \"lh sign\");\n        $assert(dmem[34] == 32'h0000ffff, \"lhu\");\n        $assert(dmem[35] == 32'h00005678, \"lhu offset 0\");\n        $assert(dmem[36] == 32'h12f80378, \"sb\");\n        $assert(dmem[37] == 32'h0003fff8, \"sh\");\n        $assert(dmem[38] == 32'h56785678, \"sh both halves\");\n        $assert(dmem[39] == 32'h00000000, \"x0 is zero\");\n\n        $finish();\n    }\n}\n"},{"name":"rv32i_rom.veryl","src":"// generated by examples/sw/build.sh from rv32i_test.S -- do not edit\nmodule RiscvTestRom (\n    i_addr: input  logic<32>,\n    o_inst: output logic<32>,\n) {\n    always_comb {\n        case i_addr[9:0] {\n            10'h000 : o_inst = 32'h00000fb7; // lui x31,0x0\n            10'h004 : o_inst = 32'h123450b7; // lui x1,0x12345\n            10'h008 : o_inst = 32'h67808093; // addi x1,x1,1656\n            10'h00c : o_inst = 32'h001fa023; // sw x1,0(x31)\n            10'h010 : o_inst = 32'h00000117; // auipc x2,0x0\n            10'h014 : o_inst = 32'h002fa223; // sw x2,4(x31)\n            10'h018 : o_inst = 32'hfffff137; // lui x2,0xfffff\n            10'h01c : o_inst = 32'h40c15113; // srai x2,x2,0xc\n            10'h020 : o_inst = 32'h002fa423; // sw x2,8(x31)\n            10'h024 : o_inst = 32'hff800193; // addi x3,x0,-8\n            10'h028 : o_inst = 32'h00300213; // addi x4,x0,3\n            10'h02c : o_inst = 32'h004182b3; // add x5,x3,x4\n            10'h030 : o_inst = 32'h005fa623; // sw x5,12(x31)\n            10'h034 : o_inst = 32'h403202b3; // sub x5,x4,x3\n            10'h038 : o_inst = 32'h005fa823; // sw x5,16(x31)\n            10'h03c : o_inst = 32'h004192b3; // sll x5,x3,x4\n            10'h040 : o_inst = 32'h005faa23; // sw x5,20(x31)\n            10'h044 : o_inst = 32'h0041d2b3; // srl x5,x3,x4\n            10'h048 : o_inst = 32'h005fac23; // sw x5,24(x31)\n            10'h04c : o_inst = 32'h4041d2b3; // sra x5,x3,x4\n            10'h050 : o_inst = 32'h005fae23; // sw x5,28(x31)\n            10'h054 : o_inst = 32'h01e21293; // slli x5,x4,0x1e\n            10'h058 : o_inst = 32'h025fa023; // sw x5,32(x31)\n            10'h05c : o_inst = 32'h01c1d293; // srli x5,x3,0x1c\n            10'h060 : o_inst = 32'h025fa223; // sw x5,36(x31)\n            10'h064 : o_inst = 32'h4011d293; // srai x5,x3,0x1\n            10'h068 : o_inst = 32'h025fa423; // sw x5,40(x31)\n            10'h06c : o_inst = 32'h0030c2b3; // xor x5,x1,x3\n            10'h070 : o_inst = 32'h025fa623; // sw x5,44(x31)\n            10'h074 : o_inst = 32'hfff24293; // xori x5,x4,-1\n            10'h078 : o_inst = 32'h025fa823; // sw x5,48(x31)\n            10'h07c : o_inst = 32'h0040e2b3; // or x5,x1,x4\n            10'h080 : o_inst = 32'h025faa23; // sw x5,52(x31)\n            10'h084 : o_inst = 32'h7f026293; // ori x5,x4,2032\n            10'h088 : o_inst = 32'h025fac23; // sw x5,56(x31)\n            10'h08c : o_inst = 32'h0030f2b3; // and x5,x1,x3\n            10'h090 : o_inst = 32'h025fae23; // sw x5,60(x31)\n            10'h094 : o_inst = 32'h0ff0f293; // andi x5,x1,255\n            10'h098 : o_inst = 32'h045fa023; // sw x5,64(x31)\n            10'h09c : o_inst = 32'h0041a2b3; // slt x5,x3,x4\n            10'h0a0 : o_inst = 32'h045fa223; // sw x5,68(x31)\n            10'h0a4 : o_inst = 32'h0041b2b3; // sltu x5,x3,x4\n            10'h0a8 : o_inst = 32'h045fa423; // sw x5,72(x31)\n            10'h0ac : o_inst = 32'hfff22293; // slti x5,x4,-1\n            10'h0b0 : o_inst = 32'h045fa623; // sw x5,76(x31)\n            10'h0b4 : o_inst = 32'hfff23293; // sltiu x5,x4,-1\n            10'h0b8 : o_inst = 32'h045fa823; // sw x5,80(x31)\n            10'h0bc : o_inst = 32'h02100313; // addi x6,x0,33\n            10'h0c0 : o_inst = 32'h006212b3; // sll x5,x4,x6\n            10'h0c4 : o_inst = 32'h045faa23; // sw x5,84(x31)\n            10'h0c8 : o_inst = 32'h00000393; // addi x7,x0,0\n            10'h0cc : o_inst = 32'h00000413; // addi x8,x0,0\n            10'h0d0 : o_inst = 32'h00420463; // beq x4,x4,d8 <_start+0xd8>\n            10'h0d4 : o_inst = 32'h0013e393; // ori x7,x7,1\n            10'h0d8 : o_inst = 32'h00418463; // beq x3,x4,e0 <_start+0xe0>\n            10'h0dc : o_inst = 32'h0023e393; // ori x7,x7,2\n            10'h0e0 : o_inst = 32'h00419463; // bne x3,x4,e8 <_start+0xe8>\n            10'h0e4 : o_inst = 32'h0043e393; // ori x7,x7,4\n            10'h0e8 : o_inst = 32'h00421463; // bne x4,x4,f0 <_start+0xf0>\n            10'h0ec : o_inst = 32'h0083e393; // ori x7,x7,8\n            10'h0f0 : o_inst = 32'h0041c463; // blt x3,x4,f8 <_start+0xf8>\n            10'h0f4 : o_inst = 32'h0103e393; // ori x7,x7,16\n            10'h0f8 : o_inst = 32'h00324463; // blt x4,x3,100 <_start+0x100>\n            10'h0fc : o_inst = 32'h0203e393; // ori x7,x7,32\n            10'h100 : o_inst = 32'h00325463; // bge x4,x3,108 <_start+0x108>\n            10'h104 : o_inst = 32'h0403e393; // ori x7,x7,64\n            10'h108 : o_inst = 32'h0041d463; // bge x3,x4,110 <_start+0x110>\n            10'h10c : o_inst = 32'h0803e393; // ori x7,x7,128\n            10'h110 : o_inst = 32'h00425463; // bge x4,x4,118 <_start+0x118>\n            10'h114 : o_inst = 32'h1003e393; // ori x7,x7,256\n            10'h118 : o_inst = 32'h00326463; // bltu x4,x3,120 <_start+0x120>\n            10'h11c : o_inst = 32'h00146413; // ori x8,x8,1\n            10'h120 : o_inst = 32'h0041e463; // bltu x3,x4,128 <_start+0x128>\n            10'h124 : o_inst = 32'h00246413; // ori x8,x8,2\n            10'h128 : o_inst = 32'h0041f463; // bgeu x3,x4,130 <_start+0x130>\n            10'h12c : o_inst = 32'h00446413; // ori x8,x8,4\n            10'h130 : o_inst = 32'h00327463; // bgeu x4,x3,138 <_start+0x138>\n            10'h134 : o_inst = 32'h00846413; // ori x8,x8,8\n            10'h138 : o_inst = 32'h00427463; // bgeu x4,x4,140 <_start+0x140>\n            10'h13c : o_inst = 32'h01046413; // ori x8,x8,16\n            10'h140 : o_inst = 32'h047fac23; // sw x7,88(x31)\n            10'h144 : o_inst = 32'h048fae23; // sw x8,92(x31)\n            10'h148 : o_inst = 32'h00000493; // addi x9,x0,0\n            10'h14c : o_inst = 32'h00500513; // addi x10,x0,5\n            10'h150 : o_inst = 32'h00a484b3; // add x9,x9,x10\n            10'h154 : o_inst = 32'hfff50513; // addi x10,x10,-1\n            10'h158 : o_inst = 32'hfe051ce3; // bne x10,x0,150 <_start+0x150>\n            10'h15c : o_inst = 32'h069fa023; // sw x9,96(x31)\n            10'h160 : o_inst = 32'h00000393; // addi x7,x0,0\n            10'h164 : o_inst = 32'h008005ef; // jal x11,16c <_start+0x16c>\n            10'h168 : o_inst = 32'h0013e393; // ori x7,x7,1\n            10'h16c : o_inst = 32'h00000617; // auipc x12,0x0\n            10'h170 : o_inst = 32'h011606e7; // jalr x13,17(x12)\n            10'h174 : o_inst = 32'h0023e393; // ori x7,x7,2\n            10'h178 : o_inst = 32'h0043e393; // ori x7,x7,4\n            10'h17c : o_inst = 32'h40c68733; // sub x14,x13,x12\n            10'h180 : o_inst = 32'h40c587b3; // sub x15,x11,x12\n            10'h184 : o_inst = 32'h067fa223; // sw x7,100(x31)\n            10'h188 : o_inst = 32'h06efa423; // sw x14,104(x31)\n            10'h18c : o_inst = 32'h06ffa623; // sw x15,108(x31)\n            10'h190 : o_inst = 32'h0c1fa023; // sw x1,192(x31)\n            10'h194 : o_inst = 32'h0c3fa223; // sw x3,196(x31)\n            10'h198 : o_inst = 32'h0c0f8283; // lb x5,192(x31)\n            10'h19c : o_inst = 32'h065fa823; // sw x5,112(x31)\n            10'h1a0 : o_inst = 32'h0c3f8283; // lb x5,195(x31)\n            10'h1a4 : o_inst = 32'h065faa23; // sw x5,116(x31)\n            10'h1a8 : o_inst = 32'h0c4f8283; // lb x5,196(x31)\n            10'h1ac : o_inst = 32'h065fac23; // sw x5,120(x31)\n            10'h1b0 : o_inst = 32'h0c4fc283; // lbu x5,196(x31)\n            10'h1b4 : o_inst = 32'h065fae23; // sw x5,124(x31)\n            10'h1b8 : o_inst = 32'h0c2f9283; // lh x5,194(x31)\n            10'h1bc : o_inst = 32'h085fa023; // sw x5,128(x31)\n            10'h1c0 : o_inst = 32'h0c4f9283; // lh x5,196(x31)\n            10'h1c4 : o_inst = 32'h085fa223; // sw x5,132(x31)\n            10'h1c8 : o_inst = 32'h0c6fd283; // lhu x5,198(x31)\n            10'h1cc : o_inst = 32'h085fa423; // sw x5,136(x31)\n            10'h1d0 : o_inst = 32'h0c0fd283; // lhu x5,192(x31)\n            10'h1d4 : o_inst = 32'h085fa623; // sw x5,140(x31)\n            10'h1d8 : o_inst = 32'h0c4f80a3; // sb x4,193(x31)\n            10'h1dc : o_inst = 32'h0c3f8123; // sb x3,194(x31)\n            10'h1e0 : o_inst = 32'h0c4f9323; // sh x4,198(x31)\n            10'h1e4 : o_inst = 32'h0c0fa283; // lw x5,192(x31)\n            10'h1e8 : o_inst = 32'h085fa823; // sw x5,144(x31)\n            10'h1ec : o_inst = 32'h0c4fa283; // lw x5,196(x31)\n            10'h1f0 : o_inst = 32'h085faa23; // sw x5,148(x31)\n            10'h1f4 : o_inst = 32'h0c0fa423; // sw x0,200(x31)\n            10'h1f8 : o_inst = 32'h0c1f9423; // sh x1,200(x31)\n            10'h1fc : o_inst = 32'h0c1f9523; // sh x1,202(x31)\n            10'h200 : o_inst = 32'h0c8fa283; // lw x5,200(x31)\n            10'h204 : o_inst = 32'h085fac23; // sw x5,152(x31)\n            10'h208 : o_inst = 32'h00500013; // addi x0,x0,5\n            10'h20c : o_inst = 32'h080fae23; // sw x0,156(x31)\n            10'h210 : o_inst = 32'h00100293; // addi x5,x0,1\n            10'h214 : o_inst = 32'h0a5fae23; // sw x5,188(x31)\n            10'h218 : o_inst = 32'h0000006f; // jal x0,218 <halt>\n            default: o_inst = 32'h00000013; // nop\n        }\n    }\n}\n"}],"synth":"RiscvCore","note":"TestRiscvCore 跑 examples/sw/rv32i_test.S（41 個結果，期望值經 spike 交叉比對）","title_en":"RV32I single-cycle CPU","note_en":"TestRiscvCore runs examples/sw/rv32i_test.S (41 results, expected values cross-checked with spike)","group_en":"RISC-V"},{"id":"soc","group":"RISC-V","title":"RISC-V SoC（FPGA）","files":[{"name":"rv32i.veryl","src":"// ==========================================\n// 1. 定義常數與列舉\n// ==========================================\npackage RiscvTypes {\n    enum AluOp: logic<4> {\n        Add,\n        Sub,\n        And,\n        Or,\n        Slt,\n        Sltu,\n        Xor,\n        Sll,\n        Srl,\n        Sra,\n    }\n\n    enum Opcode: logic<7> {\n        RType  = 7'b0110011,\n        IType  = 7'b0010011,\n        Load   = 7'b0000011,\n        Store  = 7'b0100011,\n        Branch = 7'b1100011,\n        Jal    = 7'b1101111,\n        Jalr   = 7'b1100111,\n        Lui    = 7'b0110111,\n        Auipc  = 7'b0010111,\n    }\n}\n\n// ==========================================\n// 2. 算術邏輯單元（ALU）\n// ==========================================\nmodule Alu (\n    i_op : input  RiscvTypes::AluOp,\n    i_a  : input  logic<32>,\n    i_b  : input  logic<32>,\n    o_res: output logic<32>,\n) {\n    import RiscvTypes::*;\n\n    always_comb {\n        case i_op {\n            AluOp::Add : o_res = i_a + i_b;\n            AluOp::Sub : o_res = i_a - i_b;\n            AluOp::And : o_res = i_a & i_b;\n            AluOp::Or  : o_res = i_a | i_b;\n            AluOp::Xor : o_res = i_a ^ i_b;\n            AluOp::Slt : o_res = {31'd0, $signed(i_a) <: $signed(i_b)};\n            AluOp::Sltu: o_res = {31'd0, i_a <: i_b};\n            // 移位量只取 i_b 的低 5 bit\n            AluOp::Sll: o_res = i_a << i_b[4:0];\n            AluOp::Srl: o_res = i_a >> i_b[4:0];\n            AluOp::Sra: o_res = $signed(i_a) >>> i_b[4:0];\n            default   : o_res = 32'd0;\n        }\n    }\n}\n\n// ==========================================\n// 3. 通用暫存器堆（Register File）\n// ==========================================\nmodule RegFile (\n    i_clk    : input  clock,\n    i_rst    : input  reset,\n    i_rs1_idx: input  logic<5>,\n    i_rs2_idx: input  logic<5>,\n    i_rd_idx : input  logic<5>,\n    i_rd_data: input  logic<32>,\n    i_rd_we  : input  logic,\n    o_rs1_val: output logic<32>,\n    o_rs2_val: output logic<32>,\n) {\n    var rf: logic<32> [32];\n\n    #[allow(missing_reset_statement)]\n    always_ff (i_clk, i_rst) {\n        if_reset {\n        } else if (i_rd_we && (i_rd_idx != 5'd0)) {\n            rf[i_rd_idx] = i_rd_data;\n        }\n    }\n\n    always_comb {\n        if i_rs1_idx == 5'd0 {\n            o_rs1_val = 32'd0;\n        } else {\n            o_rs1_val = rf[i_rs1_idx];\n        }\n\n        if i_rs2_idx == 5'd0 {\n            o_rs2_val = 32'd0;\n        } else {\n            o_rs2_val = rf[i_rs2_idx];\n        }\n    }\n}\n\n// ==========================================\n// 4. CPU 頂層模組（單週期 RV32I，不含 fence/ecall/ebreak/CSR）\n// ==========================================\n// 資料記憶體介面：o_dmem_addr 為位元組位址；寫入時 o_dmem_wdata 已對齊到\n// 32 bit 字中的位置，o_dmem_wstrb 指出要寫的位元組；讀取時 i_dmem_rdata\n// 是 o_dmem_addr 所在的整個字（由 CPU 取出 byte/halfword 並做符號擴展）。\nmodule RiscvCore (\n    i_clk       : input  clock,\n    i_rst       : input  reset,\n    o_imem_addr : output logic<32>,\n    i_imem_inst : input  logic<32>,\n    o_dmem_addr : output logic<32>,\n    o_dmem_wdata: output logic<32>,\n    o_dmem_wstrb: output logic<4>,\n    i_dmem_rdata: input  logic<32>,\n    o_dmem_we   : output logic,\n) {\n    import RiscvTypes::*;\n\n    var pc        : logic<32>;\n    var next_pc   : logic<32>;\n    var pc_plus_4 : logic<32>;\n    var branch_tgt: logic<32>;\n\n    var rs1_data  : logic<32>;\n    var rs2_data  : logic<32>;\n    var alu_src_b : logic<32>;\n    var alu_out   : logic<32>;\n    var imm       : logic<32>;\n    var wb_data   : logic<32>;\n    var load_data : logic<32>;\n    var store_data: logic<32>;\n    var store_strb: logic<4>;\n    var take      : logic;\n\n    var alu_op    : AluOp;\n    var arith_op  : AluOp;\n    var reg_write : logic;\n    var dmem_write: logic;\n\n    let opcode : logic<7> = i_imem_inst[6:0];\n    let rd_idx : logic<5> = i_imem_inst[11:7];\n    let funct3 : logic<3> = i_imem_inst[14:12];\n    let rs1_idx: logic<5> = i_imem_inst[19:15];\n    let rs2_idx: logic<5> = i_imem_inst[24:20];\n    let funct7 : logic<7> = i_imem_inst[31:25];\n\n    // --- 立即數解碼 ---\n    always_comb {\n        case opcode {\n            Opcode::IType, Opcode::Load, Opcode::Jalr:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:20]};\n            Opcode::Store:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[31:25], i_imem_inst[11:7]};\n            Opcode::Branch:\n                imm = {i_imem_inst[31] repeat 20, i_imem_inst[7], i_imem_inst[30:25], i_imem_inst[11:8], 1'b0};\n            Opcode::Jal:\n                imm = {i_imem_inst[31] repeat 12, i_imem_inst[19:12], i_imem_inst[20], i_imem_inst[30:21], 1'b0};\n            Opcode::Lui, Opcode::Auipc:\n                imm = {i_imem_inst[31:12], 12'd0};\n            default:\n                imm = 32'd0;\n        }\n    }\n\n    // --- 控制邏輯 ---\n    // funct7[5] 選 sub / sra；I-type 只有 srai 使用（addi 沒有減法版本）\n    let alt: logic = funct7[5] && (opcode == Opcode::RType || funct3 == 3'b101);\n\n    always_comb {\n        case funct3 {\n            3'b000 : arith_op = if alt ? AluOp::Sub : AluOp::Add;\n            3'b001 : arith_op = AluOp::Sll;\n            3'b010 : arith_op = AluOp::Slt;\n            3'b011 : arith_op = AluOp::Sltu;\n            3'b100 : arith_op = AluOp::Xor;\n            3'b101 : arith_op = if alt ? AluOp::Sra : AluOp::Srl;\n            3'b110 : arith_op = AluOp::Or;\n            default: arith_op = AluOp::And;\n        }\n    }\n\n    always_comb {\n        reg_write  = 1'b0;\n        dmem_write = 1'b0;\n        alu_op     = AluOp::Add;\n\n        case opcode {\n            Opcode::RType, Opcode::IType: {\n                reg_write = 1'b1;\n                alu_op    = arith_op;\n            }\n            Opcode::Load, Opcode::Jal, Opcode::Jalr, Opcode::Lui, Opcode::Auipc: {\n                reg_write = 1'b1;\n            }\n            Opcode::Store: {\n                dmem_write = 1'b1;\n            }\n            default: {}\n        }\n    }\n\n    // --- 分支條件（獨立的比較器，不經過 ALU）---\n    always_comb {\n        case funct3 {\n            3'b000 : take = rs1_data == rs2_data;                     // beq\n            3'b001 : take = rs1_data != rs2_data;                     // bne\n            3'b100 : take = $signed(rs1_data) <: $signed(rs2_data);   // blt\n            3'b101 : take = $signed(rs1_data) >= $signed(rs2_data);   // bge\n            3'b110 : take = rs1_data <: rs2_data;                     // bltu\n            3'b111 : take = rs1_data >= rs2_data;                     // bgeu\n            default: take = 1'b0;\n        }\n    }\n\n    // --- 載入：從整個字取出 byte / halfword ---\n    let byte_off : logic<2>  = alu_out[1:0];\n    let load_word: logic<32> = i_dmem_rdata >> {byte_off, 3'b000};\n\n    always_comb {\n        case funct3 {\n            3'b000 : load_data = {load_word[7] repeat 24, load_word[7:0]};   // lb\n            3'b001 : load_data = {load_word[15] repeat 16, load_word[15:0]}; // lh\n            3'b100 : load_data = {24'd0, load_word[7:0]};                    // lbu\n            3'b101 : load_data = {16'd0, load_word[15:0]};                   // lhu\n            default: load_data = load_word;                                  // lw\n        }\n    }\n\n    // --- 儲存：把資料複製到每個位元組位置，並產生 byte strobe ---\n    always_comb {\n        case funct3 {\n            3'b000: {\n                store_data = {rs2_data[7:0] repeat 4};\n                store_strb = 4'b0001 << byte_off;\n            }\n            3'b001: {\n                store_data = {rs2_data[15:0] repeat 2};\n                store_strb = 4'b0011 << byte_off;\n            }\n            default: {\n                store_data = rs2_data;\n                store_strb = 4'b1111;\n            }\n        }\n    }\n\n    // --- 多工器選擇 ---\n    always_comb {\n        if (opcode == Opcode::RType || opcode == Opcode::Branch) {\n            alu_src_b = rs2_data;\n        } else {\n            alu_src_b = imm;\n        }\n\n        case opcode {\n            Opcode::Load            : wb_data = load_data;\n            Opcode::Jal, Opcode::Jalr: wb_data = pc_plus_4;\n            Opcode::Lui             : wb_data = imm;\n            Opcode::Auipc           : wb_data = branch_tgt;\n            default                 : wb_data = alu_out;\n        }\n    }\n\n    // --- 模組例化 ---\n    inst u_rf: RegFile (\n        i_clk    : i_clk,\n        i_rst    : i_rst,\n        i_rs1_idx: rs1_idx,\n        i_rs2_idx: rs2_idx,\n        i_rd_idx : rd_idx,\n        i_rd_data: wb_data,\n        i_rd_we  : reg_write,\n        o_rs1_val: rs1_data,\n        o_rs2_val: rs2_data,\n    );\n\n    inst u_alu: Alu (\n        i_op : alu_op,\n        i_a  : rs1_data,\n        i_b  : alu_src_b,\n        o_res: alu_out,\n    );\n\n    // --- PC 計算 ---\n    assign pc_plus_4  = pc + 32'd4;\n    assign branch_tgt = pc + imm;\n\n    always_comb {\n        case opcode {\n            Opcode::Jal   : next_pc = branch_tgt;\n            Opcode::Jalr  : next_pc = {alu_out[31:1], 1'b0}; // (rs1 + imm) & ~1\n            Opcode::Branch: next_pc = if take ? branch_tgt : pc_plus_4;\n            default       : next_pc = pc_plus_4;\n        }\n    }\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            pc = 32'd0;\n        } else {\n            pc = next_pc;\n        }\n    }\n\n    // --- 輸出埠綁定 ---\n    assign o_imem_addr  = pc;\n    assign o_dmem_addr  = alu_out;\n    assign o_dmem_wdata = store_data;\n    assign o_dmem_wstrb = store_strb;\n    assign o_dmem_we    = dmem_write;\n}\n\n// ==========================================\n// 5. RISC-V 核心整合測試（Testbench）\n// ==========================================\n// 程式在 examples/sw/rv32i_test.S（ROM 由 examples/sw/build.sh 產生成\n// rv32i_rom.veryl），涵蓋全部 RV32I 運算指令；結果寫入 dmem[0..47]。\n#[test(test_riscv_cpu)]\nmodule TestRiscvCore {\n    // 官方 testbench 元件：clk 本身即 clock 訊號，rst 綁定 clk\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var imem_addr : logic<32>;\n    var imem_inst : logic<32>;\n    var dmem_addr : logic<32>;\n    var dmem_wdata: logic<32>;\n    var dmem_wstrb: logic<4>;\n    var dmem_rdata: logic<32>;\n    var dmem_we   : logic;\n\n    // 模擬 Data RAM：64 字（256 bytes），依 byte strobe 寫入\n    var dmem: logic<32> [64];\n\n    let wmask: logic<32> = {dmem_wstrb[3] repeat 8, dmem_wstrb[2] repeat 8, dmem_wstrb[1] repeat 8, dmem_wstrb[0] repeat 8};\n\n    #[allow(missing_reset_statement)]\n    always_ff (clk, rst) {\n        if_reset {\n        } else if dmem_we {\n            dmem[dmem_addr[7:2]] = (dmem[dmem_addr[7:2]] & ~wmask) | (dmem_wdata & wmask);\n        }\n    }\n    assign dmem_rdata = dmem[dmem_addr[7:2]];\n\n    // 程式 ROM\n    inst u_rom: RiscvTestRom (\n        i_addr: imem_addr,\n        o_inst: imem_inst,\n    );\n\n    // 例化 CPU\n    inst dut: RiscvCore (\n        i_clk       : clk,\n        i_rst       : rst,\n        o_imem_addr : imem_addr,\n        i_imem_inst : imem_inst,\n        o_dmem_addr : dmem_addr,\n        o_dmem_wdata: dmem_wdata,\n        o_dmem_wstrb: dmem_wstrb,\n        i_dmem_rdata: dmem_rdata,\n        o_dmem_we   : dmem_we,\n    );\n\n    initial {\n        // 1. 重設後釋放，開始執行\n        rst.assert();\n\n        // 2. 執行到程式結束（停在 halt 迴圈）\n        clk.next(200);\n\n        // 3. 斷言驗證（期望值與 rv32i_test.S 的註解相同）\n        $assert(dmem[47] == 32'h00000001, \"program finished\");\n        $assert(dmem[0] == 32'h12345678, \"lui + addi\");\n        $assert(dmem[1] == 32'h00000010, \"auipc\");\n        $assert(dmem[2] == 32'hffffffff, \"lui + srai\");\n        $assert(dmem[3] == 32'hfffffffb, \"add\");\n        $assert(dmem[4] == 32'h0000000b, \"sub\");\n        $assert(dmem[5] == 32'hffffffc0, \"sll\");\n        $assert(dmem[6] == 32'h1fffffff, \"srl\");\n        $assert(dmem[7] == 32'hffffffff, \"sra\");\n        $assert(dmem[8] == 32'hc0000000, \"slli\");\n        $assert(dmem[9] == 32'h0000000f, \"srli\");\n        $assert(dmem[10] == 32'hfffffffc, \"srai\");\n        $assert(dmem[11] == 32'hedcba980, \"xor\");\n        $assert(dmem[12] == 32'hfffffffc, \"xori\");\n        $assert(dmem[13] == 32'h1234567b, \"or\");\n        $assert(dmem[14] == 32'h000007f3, \"ori\");\n        $assert(dmem[15] == 32'h12345678, \"and\");\n        $assert(dmem[16] == 32'h00000078, \"andi\");\n        $assert(dmem[17] == 32'h00000001, \"slt\");\n        $assert(dmem[18] == 32'h00000000, \"sltu\");\n        $assert(dmem[19] == 32'h00000000, \"slti\");\n        $assert(dmem[20] == 32'h00000001, \"sltiu\");\n        $assert(dmem[21] == 32'h00000006, \"sll uses rs2[4:0]\");\n        $assert(dmem[22] == 32'h000000aa, \"beq/bne/blt/bge\");\n        $assert(dmem[23] == 32'h0000000a, \"bltu/bgeu\");\n        $assert(dmem[24] == 32'h0000000f, \"backward branch loop\");\n        $assert(dmem[25] == 32'h00000000, \"jal/jalr skip\");\n        $assert(dmem[26] == 32'h00000008, \"jalr link\");\n        $assert(dmem[27] == 32'hfffffffc, \"jal link\");\n        $assert(dmem[28] == 32'h00000078, \"lb\");\n        $assert(dmem[29] == 32'h00000012, \"lb offset 3\");\n        $assert(dmem[30] == 32'hfffffff8, \"lb sign\");\n        $assert(dmem[31] == 32'h000000f8, \"lbu\");\n        $assert(dmem[32] == 32'h00001234, \"lh\");\n        $assert(dmem[33] == 32'hfffffff8, \"lh sign\");\n        $assert(dmem[34] == 32'h0000ffff, \"lhu\");\n        $assert(dmem[35] == 32'h00005678, \"lhu offset 0\");\n        $assert(dmem[36] == 32'h12f80378, \"sb\");\n        $assert(dmem[37] == 32'h0003fff8, \"sh\");\n        $assert(dmem[38] == 32'h56785678, \"sh both halves\");\n        $assert(dmem[39] == 32'h00000000, \"x0 is zero\");\n\n        $finish();\n    }\n}\n"},{"name":"rv32i_rom.veryl","src":"// generated by examples/sw/build.sh from rv32i_test.S -- do not edit\nmodule RiscvTestRom (\n    i_addr: input  logic<32>,\n    o_inst: output logic<32>,\n) {\n    always_comb {\n        case i_addr[9:0] {\n            10'h000 : o_inst = 32'h00000fb7; // lui x31,0x0\n            10'h004 : o_inst = 32'h123450b7; // lui x1,0x12345\n            10'h008 : o_inst = 32'h67808093; // addi x1,x1,1656\n            10'h00c : o_inst = 32'h001fa023; // sw x1,0(x31)\n            10'h010 : o_inst = 32'h00000117; // auipc x2,0x0\n            10'h014 : o_inst = 32'h002fa223; // sw x2,4(x31)\n            10'h018 : o_inst = 32'hfffff137; // lui x2,0xfffff\n            10'h01c : o_inst = 32'h40c15113; // srai x2,x2,0xc\n            10'h020 : o_inst = 32'h002fa423; // sw x2,8(x31)\n            10'h024 : o_inst = 32'hff800193; // addi x3,x0,-8\n            10'h028 : o_inst = 32'h00300213; // addi x4,x0,3\n            10'h02c : o_inst = 32'h004182b3; // add x5,x3,x4\n            10'h030 : o_inst = 32'h005fa623; // sw x5,12(x31)\n            10'h034 : o_inst = 32'h403202b3; // sub x5,x4,x3\n            10'h038 : o_inst = 32'h005fa823; // sw x5,16(x31)\n            10'h03c : o_inst = 32'h004192b3; // sll x5,x3,x4\n            10'h040 : o_inst = 32'h005faa23; // sw x5,20(x31)\n            10'h044 : o_inst = 32'h0041d2b3; // srl x5,x3,x4\n            10'h048 : o_inst = 32'h005fac23; // sw x5,24(x31)\n            10'h04c : o_inst = 32'h4041d2b3; // sra x5,x3,x4\n            10'h050 : o_inst = 32'h005fae23; // sw x5,28(x31)\n            10'h054 : o_inst = 32'h01e21293; // slli x5,x4,0x1e\n            10'h058 : o_inst = 32'h025fa023; // sw x5,32(x31)\n            10'h05c : o_inst = 32'h01c1d293; // srli x5,x3,0x1c\n            10'h060 : o_inst = 32'h025fa223; // sw x5,36(x31)\n            10'h064 : o_inst = 32'h4011d293; // srai x5,x3,0x1\n            10'h068 : o_inst = 32'h025fa423; // sw x5,40(x31)\n            10'h06c : o_inst = 32'h0030c2b3; // xor x5,x1,x3\n            10'h070 : o_inst = 32'h025fa623; // sw x5,44(x31)\n            10'h074 : o_inst = 32'hfff24293; // xori x5,x4,-1\n            10'h078 : o_inst = 32'h025fa823; // sw x5,48(x31)\n            10'h07c : o_inst = 32'h0040e2b3; // or x5,x1,x4\n            10'h080 : o_inst = 32'h025faa23; // sw x5,52(x31)\n            10'h084 : o_inst = 32'h7f026293; // ori x5,x4,2032\n            10'h088 : o_inst = 32'h025fac23; // sw x5,56(x31)\n            10'h08c : o_inst = 32'h0030f2b3; // and x5,x1,x3\n            10'h090 : o_inst = 32'h025fae23; // sw x5,60(x31)\n            10'h094 : o_inst = 32'h0ff0f293; // andi x5,x1,255\n            10'h098 : o_inst = 32'h045fa023; // sw x5,64(x31)\n            10'h09c : o_inst = 32'h0041a2b3; // slt x5,x3,x4\n            10'h0a0 : o_inst = 32'h045fa223; // sw x5,68(x31)\n            10'h0a4 : o_inst = 32'h0041b2b3; // sltu x5,x3,x4\n            10'h0a8 : o_inst = 32'h045fa423; // sw x5,72(x31)\n            10'h0ac : o_inst = 32'hfff22293; // slti x5,x4,-1\n            10'h0b0 : o_inst = 32'h045fa623; // sw x5,76(x31)\n            10'h0b4 : o_inst = 32'hfff23293; // sltiu x5,x4,-1\n            10'h0b8 : o_inst = 32'h045fa823; // sw x5,80(x31)\n            10'h0bc : o_inst = 32'h02100313; // addi x6,x0,33\n            10'h0c0 : o_inst = 32'h006212b3; // sll x5,x4,x6\n            10'h0c4 : o_inst = 32'h045faa23; // sw x5,84(x31)\n            10'h0c8 : o_inst = 32'h00000393; // addi x7,x0,0\n            10'h0cc : o_inst = 32'h00000413; // addi x8,x0,0\n            10'h0d0 : o_inst = 32'h00420463; // beq x4,x4,d8 <_start+0xd8>\n            10'h0d4 : o_inst = 32'h0013e393; // ori x7,x7,1\n            10'h0d8 : o_inst = 32'h00418463; // beq x3,x4,e0 <_start+0xe0>\n            10'h0dc : o_inst = 32'h0023e393; // ori x7,x7,2\n            10'h0e0 : o_inst = 32'h00419463; // bne x3,x4,e8 <_start+0xe8>\n            10'h0e4 : o_inst = 32'h0043e393; // ori x7,x7,4\n            10'h0e8 : o_inst = 32'h00421463; // bne x4,x4,f0 <_start+0xf0>\n            10'h0ec : o_inst = 32'h0083e393; // ori x7,x7,8\n            10'h0f0 : o_inst = 32'h0041c463; // blt x3,x4,f8 <_start+0xf8>\n            10'h0f4 : o_inst = 32'h0103e393; // ori x7,x7,16\n            10'h0f8 : o_inst = 32'h00324463; // blt x4,x3,100 <_start+0x100>\n            10'h0fc : o_inst = 32'h0203e393; // ori x7,x7,32\n            10'h100 : o_inst = 32'h00325463; // bge x4,x3,108 <_start+0x108>\n            10'h104 : o_inst = 32'h0403e393; // ori x7,x7,64\n            10'h108 : o_inst = 32'h0041d463; // bge x3,x4,110 <_start+0x110>\n            10'h10c : o_inst = 32'h0803e393; // ori x7,x7,128\n            10'h110 : o_inst = 32'h00425463; // bge x4,x4,118 <_start+0x118>\n            10'h114 : o_inst = 32'h1003e393; // ori x7,x7,256\n            10'h118 : o_inst = 32'h00326463; // bltu x4,x3,120 <_start+0x120>\n            10'h11c : o_inst = 32'h00146413; // ori x8,x8,1\n            10'h120 : o_inst = 32'h0041e463; // bltu x3,x4,128 <_start+0x128>\n            10'h124 : o_inst = 32'h00246413; // ori x8,x8,2\n            10'h128 : o_inst = 32'h0041f463; // bgeu x3,x4,130 <_start+0x130>\n            10'h12c : o_inst = 32'h00446413; // ori x8,x8,4\n            10'h130 : o_inst = 32'h00327463; // bgeu x4,x3,138 <_start+0x138>\n            10'h134 : o_inst = 32'h00846413; // ori x8,x8,8\n            10'h138 : o_inst = 32'h00427463; // bgeu x4,x4,140 <_start+0x140>\n            10'h13c : o_inst = 32'h01046413; // ori x8,x8,16\n            10'h140 : o_inst = 32'h047fac23; // sw x7,88(x31)\n            10'h144 : o_inst = 32'h048fae23; // sw x8,92(x31)\n            10'h148 : o_inst = 32'h00000493; // addi x9,x0,0\n            10'h14c : o_inst = 32'h00500513; // addi x10,x0,5\n            10'h150 : o_inst = 32'h00a484b3; // add x9,x9,x10\n            10'h154 : o_inst = 32'hfff50513; // addi x10,x10,-1\n            10'h158 : o_inst = 32'hfe051ce3; // bne x10,x0,150 <_start+0x150>\n            10'h15c : o_inst = 32'h069fa023; // sw x9,96(x31)\n            10'h160 : o_inst = 32'h00000393; // addi x7,x0,0\n            10'h164 : o_inst = 32'h008005ef; // jal x11,16c <_start+0x16c>\n            10'h168 : o_inst = 32'h0013e393; // ori x7,x7,1\n            10'h16c : o_inst = 32'h00000617; // auipc x12,0x0\n            10'h170 : o_inst = 32'h011606e7; // jalr x13,17(x12)\n            10'h174 : o_inst = 32'h0023e393; // ori x7,x7,2\n            10'h178 : o_inst = 32'h0043e393; // ori x7,x7,4\n            10'h17c : o_inst = 32'h40c68733; // sub x14,x13,x12\n            10'h180 : o_inst = 32'h40c587b3; // sub x15,x11,x12\n            10'h184 : o_inst = 32'h067fa223; // sw x7,100(x31)\n            10'h188 : o_inst = 32'h06efa423; // sw x14,104(x31)\n            10'h18c : o_inst = 32'h06ffa623; // sw x15,108(x31)\n            10'h190 : o_inst = 32'h0c1fa023; // sw x1,192(x31)\n            10'h194 : o_inst = 32'h0c3fa223; // sw x3,196(x31)\n            10'h198 : o_inst = 32'h0c0f8283; // lb x5,192(x31)\n            10'h19c : o_inst = 32'h065fa823; // sw x5,112(x31)\n            10'h1a0 : o_inst = 32'h0c3f8283; // lb x5,195(x31)\n            10'h1a4 : o_inst = 32'h065faa23; // sw x5,116(x31)\n            10'h1a8 : o_inst = 32'h0c4f8283; // lb x5,196(x31)\n            10'h1ac : o_inst = 32'h065fac23; // sw x5,120(x31)\n            10'h1b0 : o_inst = 32'h0c4fc283; // lbu x5,196(x31)\n            10'h1b4 : o_inst = 32'h065fae23; // sw x5,124(x31)\n            10'h1b8 : o_inst = 32'h0c2f9283; // lh x5,194(x31)\n            10'h1bc : o_inst = 32'h085fa023; // sw x5,128(x31)\n            10'h1c0 : o_inst = 32'h0c4f9283; // lh x5,196(x31)\n            10'h1c4 : o_inst = 32'h085fa223; // sw x5,132(x31)\n            10'h1c8 : o_inst = 32'h0c6fd283; // lhu x5,198(x31)\n            10'h1cc : o_inst = 32'h085fa423; // sw x5,136(x31)\n            10'h1d0 : o_inst = 32'h0c0fd283; // lhu x5,192(x31)\n            10'h1d4 : o_inst = 32'h085fa623; // sw x5,140(x31)\n            10'h1d8 : o_inst = 32'h0c4f80a3; // sb x4,193(x31)\n            10'h1dc : o_inst = 32'h0c3f8123; // sb x3,194(x31)\n            10'h1e0 : o_inst = 32'h0c4f9323; // sh x4,198(x31)\n            10'h1e4 : o_inst = 32'h0c0fa283; // lw x5,192(x31)\n            10'h1e8 : o_inst = 32'h085fa823; // sw x5,144(x31)\n            10'h1ec : o_inst = 32'h0c4fa283; // lw x5,196(x31)\n            10'h1f0 : o_inst = 32'h085faa23; // sw x5,148(x31)\n            10'h1f4 : o_inst = 32'h0c0fa423; // sw x0,200(x31)\n            10'h1f8 : o_inst = 32'h0c1f9423; // sh x1,200(x31)\n            10'h1fc : o_inst = 32'h0c1f9523; // sh x1,202(x31)\n            10'h200 : o_inst = 32'h0c8fa283; // lw x5,200(x31)\n            10'h204 : o_inst = 32'h085fac23; // sw x5,152(x31)\n            10'h208 : o_inst = 32'h00500013; // addi x0,x0,5\n            10'h20c : o_inst = 32'h080fae23; // sw x0,156(x31)\n            10'h210 : o_inst = 32'h00100293; // addi x5,x0,1\n            10'h214 : o_inst = 32'h0a5fae23; // sw x5,188(x31)\n            10'h218 : o_inst = 32'h0000006f; // jal x0,218 <halt>\n            default: o_inst = 32'h00000013; // nop\n        }\n    }\n}\n"},{"name":"soc.veryl","src":"// ==========================================\n// FPGA 用的 RISC-V SoC：RiscvCore（examples/src/rv32i.veryl）\n// + 程式 ROM + 16 字資料 RAM + LED 暫存器（記憶體映射於 0x100）\n// 頂層只有 clock / reset / 8 顆 LED，可放進 iCE40UP5K（SG48）\n// ==========================================\n\n// 程式：用迴圈算 Fibonacci(10) = 55，寫到 RAM[0] 與 LED\nmodule ProgRom (\n    i_addr: input  logic<32>,\n    o_inst: output logic<32>,\n) {\n    always_comb {\n        case i_addr[7:0] {\n            8'h00  : o_inst = 32'h00000093; // addi x1, x0, 0      a = 0\n            8'h04  : o_inst = 32'h00100113; // addi x2, x0, 1      b = 1\n            8'h08  : o_inst = 32'h00a00213; // addi x4, x0, 10     n = 10\n            8'h0c  : o_inst = 32'h00000293; // addi x5, x0, 0      i = 0\n            8'h10  : o_inst = 32'h00428c63; // loop: beq x5, x4, done (+24)\n            8'h14  : o_inst = 32'h002081b3; // add  x3, x1, x2     t = a + b\n            8'h18  : o_inst = 32'h00010093; // addi x1, x2, 0      a = b\n            8'h1c  : o_inst = 32'h00018113; // addi x2, x3, 0      b = t\n            8'h20  : o_inst = 32'h00128293; // addi x5, x5, 1      i += 1\n            8'h24  : o_inst = 32'hfedff06f; // jal  x0, loop (-20)\n            8'h28  : o_inst = 32'h00102023; // done: sw x1, 0(x0)  RAM[0] = a\n            8'h2c  : o_inst = 32'h10102023; // sw   x1, 256(x0)    LED = a\n            8'h30  : o_inst = 32'h0000006f; // jal  x0, 0          halt\n            default: o_inst = 32'h00000013; // nop\n        }\n    }\n}\n\nmodule RiscvSoc (\n    i_clk: input  clock,\n    i_rst: input  reset,\n    o_led: output logic<8>,\n) {\n    var imem_addr : logic<32>;\n    var imem_inst : logic<32>;\n    var dmem_addr : logic<32>;\n    var dmem_wdata: logic<32>;\n    var dmem_wstrb: logic<4>;\n    var dmem_rdata: logic<32>;\n    var dmem_we   : logic;\n    var dmem      : logic<32> [16];\n    var led       : logic<8>;\n\n    // 0x000-0x03f: data RAM, 0x100: LED register\n    let is_led: logic = dmem_addr[8];\n    let wmask : logic<32> = {dmem_wstrb[3] repeat 8, dmem_wstrb[2] repeat 8, dmem_wstrb[1] repeat 8, dmem_wstrb[0] repeat 8};\n\n    inst u_rom: ProgRom (\n        i_addr: imem_addr,\n        o_inst: imem_inst,\n    );\n\n    inst u_cpu: RiscvCore (\n        i_clk                    ,\n        i_rst                    ,\n        o_imem_addr : imem_addr  ,\n        i_imem_inst : imem_inst  ,\n        o_dmem_addr : dmem_addr  ,\n        o_dmem_wdata: dmem_wdata ,\n        o_dmem_wstrb: dmem_wstrb ,\n        i_dmem_rdata: dmem_rdata ,\n        o_dmem_we   : dmem_we    ,\n    );\n\n    #[allow(missing_reset_statement)]\n    always_ff (i_clk, i_rst) {\n        if_reset {\n        } else if dmem_we && !is_led {\n            dmem[dmem_addr[5:2]] = (dmem[dmem_addr[5:2]] & ~wmask) | (dmem_wdata & wmask);\n        }\n    }\n    assign dmem_rdata = dmem[dmem_addr[5:2]];\n\n    always_ff (i_clk, i_rst) {\n        if_reset {\n            led = 8'd0;\n        } else if dmem_we && is_led && dmem_wstrb[0] {\n            led = dmem_wdata[7:0];\n        }\n    }\n    assign o_led = led;\n}\n\n#[test(test_riscv_soc)]\nmodule TestRiscvSoc {\n    inst clk: $tb::clock_gen;\n    inst rst: $tb::reset_gen(clk);\n\n    var led: logic<8>;\n\n    inst dut: RiscvSoc (\n        i_clk: clk,\n        i_rst: rst,\n        o_led: led,\n    );\n\n    initial {\n        rst.assert();\n        clk.next(100);\n        $assert(led == 8'd55, \"fib(10) = 55 on the LEDs\");\n        $finish();\n    }\n}\n"}],"synth":"RiscvSoc","pcf":"# iCEBreaker (iCE40UP5K-SG48): 12 MHz clock, user button (active low),\n# 8 LEDs on PMOD1A (e.g. the 8-LED PMOD). Adjust the pins for other boards.\nset_io i_clk    35\nset_io i_rst    10\nset_io o_led[0] 4\nset_io o_led[1] 2\nset_io o_led[2] 47\nset_io o_led[3] 45\nset_io o_led[4] 3\nset_io o_led[5] 48\nset_io o_led[6] 46\nset_io o_led[7] 44\n","note":"Fibonacci(10) = 55 → LED；iCEBreaker 腳位","title_en":"RISC-V SoC (FPGA)","note_en":"Fibonacci(10) = 55 → LEDs; iCEBreaker pins","group_en":"RISC-V"},{"id":"alu_fail","group":"其他","title":"Alu（含一個故意失敗的斷言）","files":[{"name":"alu.veryl","src":"module Alu (\n    i_a  : input  logic<8>,\n    i_b  : input  logic<8>,\n    i_op : input  logic<2>,\n    o_y  : output logic<8>,\n    o_zero: output logic,\n) {\n    always_comb {\n        case i_op {\n            0: o_y = i_a + i_b;\n            1: o_y = i_a - i_b;\n            2: o_y = i_a & i_b;\n            default: o_y = i_a ^ i_b;\n        }\n    }\n    assign o_zero = o_y == 0;\n}\n\nmodule PopCount (\n    i_d: input  logic<8>,\n    o_n: output logic<4>,\n) {\n    always_comb {\n        o_n = 0;\n        for i in 0..8 {\n            o_n += i_d[i];\n        }\n    }\n}\n\n#[test(alu_test)]\nmodule tb_alu {\n    inst clk: $tb::clock_gen;\n    var a: logic<8>;\n    var b: logic<8>;\n    var op: logic<2>;\n    var y: logic<8>;\n    var z: logic;\n    var n: logic<4>;\n    inst u_alu: Alu (i_a: a, i_b: b, i_op: op, o_y: y, o_zero: z);\n    inst u_pc: PopCount (i_d: a, o_n: n);\n\n    initial {\n        a = 8'd200; b = 8'd100; op = 0;\n        clk.next(1);\n        $display(\"200+100 = %d (wraps)\", y);\n        $assert(y == 44);\n        op = 1; clk.next(1);\n        $display(\"200-100 = %d\", y);\n        $assert(y == 100);\n        op = 2; a = 8'hF0; b = 8'h3C; clk.next(1);\n        $display(\"F0&3C = %h popcount(a)=%d\", y, n);\n        $assert(y == 8'h30);\n        $assert(n == 4);\n        op = 3; b = a; clk.next(1);\n        $display(\"a^a = %d zero=%b\", y, z);\n        $assert(z == 1'b1);\n        $assert(y == 99, \"this one should fail on purpose\");\n        $finish();\n    }\n}\n"}],"synth":"Alu","note":"示範斷言失敗的樣子：tb_alu 有一個 \"should fail on purpose\" 的斷言","title_en":"Alu (with an assertion that fails on purpose)","note_en":"What a failing assertion looks like: tb_alu has a \"should fail on purpose\" assertion","group_en":"Other"}];
